import math
import numpy as np

BOX_N = 32
MAX_BOX_ATR = 6.0
SIZE = 0.5
HARD_STOP_ATR = 2.0
TRAIL_ATR = 1.5


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    # Box: the 32 bars BEFORE the current bar
    box_hi = float(ind.highest(hist.high, BOX_N)[-2])
    box_lo = float(ind.lowest(hist.low, BOX_N)[-2])

    long_sig = False
    short_sig = False
    if not (math.isnan(atr) or math.isnan(box_hi) or math.isnan(box_lo)) and atr > 0:
        if (box_hi - box_lo) <= MAX_BOX_ATR * atr:
            if close > box_hi:
                long_sig = True
            elif close < box_lo:
                short_sig = True

    # Flat (including after a stop fill): clear trade state
    if pos == 0:
        for k in ("dir", "entry", "eatr", "ext", "tbar"):
            if k in state:
                del state[k]

        if long_sig:
            state["dir"] = 1
            state["entry"] = float(close)
            state["eatr"] = atr
            state["ext"] = float(close)
            state["tbar"] = t
            stop = close - HARD_STOP_ATR * atr
            return {"target": SIZE, "stop": stop, "take": None}
        if short_sig:
            state["dir"] = -1
            state["entry"] = float(close)
            state["eatr"] = atr
            state["ext"] = float(close)
            state["tbar"] = t
            stop = close + HARD_STOP_ATR * atr
            return {"target": -SIZE, "stop": stop, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # In a trade
    d = int(state.get("dir", 1 if pos > 0 else -1))
    entry = float(state.get("entry", close))
    eatr = float(state.get("eatr", atr))
    ext = float(state.get("ext", close))

    if d > 0:
        ext = max(ext, float(high))
        state["ext"] = ext
        stop = max(entry - HARD_STOP_ATR * eatr, ext - TRAIL_ATR * eatr)
        if short_sig:
            return {"target": 0.0, "stop": stop, "take": None}
        return {"target": pos, "stop": stop, "take": None}
    else:
        ext = min(ext, float(low))
        state["ext"] = ext
        stop = min(entry + HARD_STOP_ATR * eatr, ext + TRAIL_ATR * eatr)
        if long_sig:
            return {"target": 0.0, "stop": stop, "take": None}
        return {"target": pos, "stop": stop, "take": None}

import math
import numpy as np


def clear_trade(state):
    for k in ("in_trade", "entry", "eatr", "hi", "adds", "be"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    close = hist.close
    c = close[-1]
    t = len(hist) - 1

    macd_line, sig_line, _ = ind.macd(close, 5, 35, 5)
    m0, s0 = macd_line[-1], sig_line[-1]
    m1, s1 = macd_line[-2], sig_line[-2]
    valid = not (math.isnan(m0) or math.isnan(s0) or math.isnan(m1) or math.isnan(s1))
    bull_cross = valid and (m1 <= s1) and (m0 > s0)
    bear_cross = valid and (m1 >= s1) and (m0 < s0)

    # A stop fill (or any external flat) resets the trade
    if state.get("in_trade", False) and pos == 0.0:
        clear_trade(state)

    if state.get("in_trade", False):
        entry = state["entry"]
        eatr = state["eatr"]
        hi = max(state["hi"], hist.high[-1])
        state["hi"] = hi

        # Opposite signal closes the trade
        if bear_cross:
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        # Breakeven activation (close-based, inclusive)
        if not state["be"] and c >= entry + eatr:
            state["be"] = True

        target = pos
        # Pyramid once: +0.5 when price moved >= 2 entry ATR since last add (entry)
        if state["adds"] < 1 and c >= entry + 2.0 * eatr:
            state["adds"] = 1
            target = min(1.0, pos + 0.5)

        stop = None
        if state["be"]:
            be_stop = entry
            trail = hi - 2.0 * eatr
            stop = max(be_stop, trail)

        return {"target": target, "stop": stop, "take": None}

    # Flat: look for entry
    if pos == 0.0 and bull_cross:
        h4 = hist.htf(240)
        if len(h4) >= 1:
            e20 = ind.ema(h4.close, 20)[-1]
            if not math.isnan(e20) and h4.close[-1] > e20:
                atr = ind.atr(hist, 14)[-1]
                if not math.isnan(atr) and atr > 0:
                    state["in_trade"] = True
                    state["entry"] = float(c)
                    state["eatr"] = float(atr)
                    state["hi"] = float(hist.high[-1])
                    state["adds"] = 0
                    state["be"] = False
                    return {"target": 0.5, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

N_CHANNEL = 48
ATR_MULT = 2.0
MAX_BARS = 32
SIZE = 0.5


def clear_trade(state):
    for k in ("dir", "t0", "atr", "best", "stop"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    upper = ind.highest(hist.high, N_CHANNEL)[-2]
    lower = ind.lowest(hist.low, N_CHANNEL)[-2]
    atr = ind.atr(hist, 14)[-1]

    long_sig = (not math.isnan(upper)) and close > upper
    short_sig = (not math.isnan(lower)) and close < lower

    # Detect trade ended (stopped out or closed) -> reset state
    if "dir" in state and pos == 0.0 and t > state["t0"]:
        clear_trade(state)

    # Manage open trade
    if "dir" in state and pos != 0.0:
        d = state["dir"]
        t0 = state["t0"]
        eatr = state["atr"]
        if d > 0:
            best = max(state["best"], high)
            stop = max(state["stop"], best - ATR_MULT * eatr)
        else:
            best = min(state["best"], low)
            stop = min(state["stop"], best + ATR_MULT * eatr)
        state["best"] = best
        state["stop"] = stop

        opposite = (d > 0 and short_sig) or (d < 0 and long_sig)
        time_exit = (t + 1 - t0) >= MAX_BARS
        if opposite or time_exit:
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": stop, "take": None}

    # Flat: look for entries
    if pos == 0.0:
        if "dir" in state:
            clear_trade(state)
        if math.isnan(atr) or atr <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        if long_sig and not short_sig:
            stop = close - ATR_MULT * atr
            state["dir"] = 1
            state["t0"] = t
            state["atr"] = float(atr)
            state["best"] = float(close)
            state["stop"] = float(stop)
            return {"target": SIZE, "stop": stop, "take": None}
        if short_sig and not long_sig:
            stop = close + ATR_MULT * atr
            state["dir"] = -1
            state["t0"] = t
            state["atr"] = float(atr)
            state["best"] = float(close)
            state["stop"] = float(stop)
            return {"target": -SIZE, "stop": stop, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # Position without state (shouldn't happen): flatten
    return {"target": 0.0, "stop": None, "take": None}

