import numpy as np


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])

    macd_line, signal_line, _ = ind.macd(close, 5, 35, 5)
    cross_up = False
    cross_dn = False
    if t >= 1:
        m0 = macd_line[-1]
        s0 = signal_line[-1]
        m1 = macd_line[-2]
        s1 = signal_line[-2]
        if not (np.isnan(m0) or np.isnan(s0) or np.isnan(m1) or np.isnan(s1)):
            cross_up = (m1 <= s1) and (m0 > s0)
            cross_dn = (m1 >= s1) and (m0 < s0)

    # Manage live trade
    if state.get("in_trade", False):
        if pos == 0.0:
            # Position went flat (stop/take fill or signal exit executed)
            state["in_trade"] = False
            state["flat_t"] = t
        else:
            d = state.get("dir", 0)
            if (d > 0 and cross_dn) or (d < 0 and cross_up):
                return {"target": 0.0, "stop": None, "take": None}
            return {"target": pos, "stop": state["stop"], "take": state["take"]}

    # Entry logic (only when flat)
    if pos != 0.0:
        return {"target": pos, "stop": None, "take": None}

    flat_t = state.get("flat_t", -1000000000)
    if t - flat_t < 4:
        return {"target": 0.0, "stop": None, "take": None}

    if not (cross_up or cross_dn):
        return {"target": 0.0, "stop": None, "take": None}

    h = hist.htf(60)
    if len(h) < 20:
        return {"target": 0.0, "stop": None, "take": None}
    hema = ind.ema(h.close, 20)
    e = float(hema[-1])
    if np.isnan(e):
        return {"target": 0.0, "stop": None, "take": None}

    atr = ind.atr(hist, 14)
    a = float(atr[-1])
    if np.isnan(a) or a <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    size = 0.0025 * c / (3.0 * a)
    size = min(1.0, max(0.05, size))

    if cross_up and c > e:
        stop = c - 2.0 * a
        take = c + 3.0 * a
        state["in_trade"] = True
        state["dir"] = 1
        state["stop"] = stop
        state["take"] = take
        return {"target": size, "stop": stop, "take": take}

    if cross_dn and c < e:
        stop = c + 2.0 * a
        take = c - 3.0 * a
        state["in_trade"] = True
        state["dir"] = -1
        state["stop"] = stop
        state["take"] = take
        return {"target": -size, "stop": stop, "take": take}

    return {"target": 0.0, "stop": None, "take": None}

