import math
import numpy as np

COOLDOWN = 4
STEP = 0.25
MAX_ADDS = 2
MAX_SIZE = 1.0
TRAIL_ATR = 4.0
ADD_ATR = 1.0


def clear_trade(state):
    for k in ("dir", "size", "entry_bar", "eatr", "last_add", "adds", "extreme"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])
    hi = float(hist.high[-1])
    lo = float(hist.low[-1])

    macd_line, sig_line, _ = ind.macd(close, 5, 35, 5)
    atr = ind.atr(hist, 14)
    a = float(atr[-1])

    m0, m1 = float(macd_line[-1]), float(macd_line[-2])
    s0, s1 = float(sig_line[-1]), float(sig_line[-2])
    valid = not (math.isnan(m0) or math.isnan(m1) or math.isnan(s0) or math.isnan(s1))
    cross_up = valid and m1 <= s1 and m0 > s0
    cross_dn = valid and m1 >= s1 and m0 < s0

    d = int(state.get("dir", 0))

    # Detect trade closed by stop fill
    if d != 0 and abs(pos) < 1e-9 and t > int(state.get("entry_bar", t)):
        state["exit_bar"] = t
        clear_trade(state)
        d = 0

    if d != 0:
        eatr = float(state["eatr"])
        ext = float(state["extreme"])
        if t > int(state["entry_bar"]):
            if d > 0:
                ext = max(ext, hi)
            else:
                ext = min(ext, lo)
            state["extreme"] = ext

        # Opposite signal -> exit at next open
        if (d > 0 and cross_dn) or (d < 0 and cross_up):
            state["exit_bar"] = t + 1
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        size = float(state["size"])
        adds = int(state["adds"])
        last_add = float(state["last_add"])
        if adds < MAX_ADDS and size < MAX_SIZE - 1e-9:
            if d * (c - last_add) >= ADD_ATR * eatr:
                size = min(MAX_SIZE, size + STEP)
                state["size"] = size
                state["adds"] = adds + 1
                state["last_add"] = c

        if d > 0:
            stop = ext - TRAIL_ATR * eatr
        else:
            stop = ext + TRAIL_ATR * eatr
        return {"target": d * size, "stop": stop, "take": None}

    # Flat
    if "exit_bar" in state and t - int(state["exit_bar"]) < COOLDOWN:
        return {"target": 0.0, "stop": None, "take": None}

    if math.isnan(a) or a <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    nd = 0
    if cross_up:
        nd = 1
    elif cross_dn:
        nd = -1
    if nd == 0:
        return {"target": 0.0, "stop": None, "take": None}

    state["dir"] = nd
    state["size"] = STEP
    state["entry_bar"] = t
    state["eatr"] = a
    state["last_add"] = c
    state["adds"] = 0
    state["extreme"] = c
    stop = c - TRAIL_ATR * a if nd > 0 else c + TRAIL_ATR * a
    return {"target": nd * STEP, "stop": stop, "take": None}

