    cross_dn = (m1 >= s1) and (m0 < s0)

    atr_arr = ind.atr(hist, 14)
    atr_now = float(atr_arr[-1])

    # Detect a trade closed by a stop/take fill
    if state.get("in_trade", False):
        if pos == 0.0 and t > state.get("entry_t", t):
            state["in_trade"] = False

    # Manage the live trade
    if state.get("in_trade", False):
        d = state["dir"]
        a = state["atr"]
        anchor = state["anchor"]
        entry_t = state["entry_t"]

        # Opposite MACD cross -> exit flat at the next open
        if (d > 0 and cross_dn) or (d < 0 and cross_up):
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        # Hard time stop at 64 bars
        if t - entry_t >= 64:
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        # Ratchet the whole box 1 ATR in our favour
        if d > 0:
            if c >= anchor + a:
                anchor += a
        else:
            if c <= anchor - a:
                anchor -= a
        state["anchor"] = anchor

        if d > 0:
            stop = anchor - 2.0 * a
            take = anchor + 3.0 * a
        else:
            stop = anchor + 2.0 * a
            take = anchor - 3.0 * a
        return {"target": 0.5 * d, "stop": stop, "take": take}

    # Flat: look for an entry
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    if not (cross_up or cross_dn):
        return {"target": 0.0, "stop": None, "take": None}

    if not (atr_now > 0.0) or math.isnan(atr_now):
        return {"target": 0.0, "stop": None, "take": None}

    h = hist.htf(60)
    if len(h) < 20:
        return {"target": 0.0, "stop": None, "take": None}
