    hc = float(h.close[-1])
    he = float(hema[-1])
    if math.isnan(he):
        return {"target": 0.0, "stop": None, "take": None}

    d = 0
    if cross_up and hc > he:
        d = 1
    elif cross_dn and hc < he:
        d = -1
    if d == 0:
        return {"target": 0.0, "stop": None, "take": None}

    state["in_trade"] = True
    state["dir"] = d
    state["atr"] = atr_now
    state["anchor"] = c
    state["entry_t"] = t

    if d > 0:
        stop = c - 2.0 * atr_now
        take = c + 3.0 * atr_now
    else:
        stop = c + 2.0 * atr_now
        take = c - 3.0 * atr_now
    return {"target": 0.5 * d, "stop": stop, "take": take}

import math
import numpy as np


def clear_trade(state):
    for k in ("tr_dir", "tr_t", "tr_atr", "tr_ext"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    hh = ind.highest(hist.high, 96)
    ll = ind.lowest(hist.low, 96)
    prior_high = float(hh[-2])
    prior_low = float(ll[-2])

    # 1h filter
    h1 = hist.htf(60)
    long_ok = False
    short_ok = False
    if len(h1) >= 1:
        e = ind.ema(h1.close, 20)
        c1 = float(h1.close[-1])
        e1 = float(e[-1])
        if not (math.isnan(c1) or math.isnan(e1)):
            long_ok = c1 > e1
            short_ok = c1 < e1

    # retest signal against existing arm
    long_sig = False
    short_sig = False
    arm_dir = state.get("arm_dir", 0)
    if arm_dir != 0:
        arm_t = state.get("arm_t", -10**9)
        lvl = state.get("arm_lvl", 0.0)
        if 1 <= t - arm_t <= 8:
            if arm_dir == 1 and low <= lvl and long_ok:
                long_sig = True
            elif arm_dir == -1 and high >= lvl and short_ok:
                short_sig = True
        elif t - arm_t > 8:
            state["arm_dir"] = 0

    # update arming with fresh breakout (level condition)
    if not math.isnan(prior_high) and not math.isnan(prior_low):
        if close > prior_high:
            state["arm_dir"] = 1
            state["arm_t"] = t
            state["arm_lvl"] = prior_high
        elif close < prior_low:
            state["arm_dir"] = -1
            state["arm_t"] = t
            state["arm_lvl"] = prior_low

    # manage existing trade
    if "tr_dir" in state:
        tr_t = state["tr_t"]
        if pos == 0.0 and t > tr_t:
            clear_trade(state)
        else:
            d = state["tr_dir"]
            eatr = state["tr_atr"]
            if t > tr_t:
                if d == 1:
                    state["tr_ext"] = max(state["tr_ext"], high)
                else:
                    state["tr_ext"] = min(state["tr_ext"], low)
            ext = state["tr_ext"]
            if t - tr_t >= 32 or (d == 1 and short_sig) or (d == -1 and long_sig):
                clear_trade(state)
                return {"target": 0.0, "stop": None, "take": None}
            stop = ext - 3.0 * eatr if d == 1 else ext + 3.0 * eatr
            return {"target": pos if t > tr_t else state.get("tr_size", pos),
                    "stop": stop, "take": None}

    # flat: entries
    if pos == 0.0 and (long_sig or short_sig) and atr > 0 and not math.isnan(atr):
        size = 0.01 * close / (2.0 * atr)
        size = min(1.0, max(0.05, size))
        d = 1 if long_sig else -1
        state["tr_dir"] = d
        state["tr_t"] = t
        state["tr_atr"] = atr
        state["tr_ext"] = close
        state["tr_size"] = d * size
        stop = close - 3.0 * atr if d == 1 else close + 3.0 * atr
        return {"target": d * size, "stop": stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

