def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]

    # Breakout levels: computed over the 48 bars BEFORE the current bar
    hh = ind.highest(hist.high, CHANNEL_N)[-2]
    ll = ind.lowest(hist.low, CHANNEL_N)[-2]
    atr = ind.atr(hist, ATR_N)[-1]

    long_sig = (not math.isnan(hh)) and close > hh
    short_sig = (not math.isnan(ll)) and close < ll

