        d = state.get("dir", 1 if pos > 0 else -1)
        entry_t = state.get("entry_t", t)
        if "entry_t" not in state:
            state["entry_t"] = entry_t
            state["dir"] = d

        # Opposite signal: exit at the next open
        if d > 0 and short_sig:
            return {"target": 0.0, "stop": None, "take": None}
        if d < 0 and long_sig:
