    m0, m1 = float(macd_line[-1]), float(macd_line[-2])
    s0, s1 = float(sig_line[-1]), float(sig_line[-2])
    bull = (m1 <= s1) and (m0 > s0)
    bear = (m1 >= s1) and (m0 < s0)

    d = int(state.get("dir", 0))

    # Detect trade closed (stop fill or executed exit)
    if d != 0 and pos == 0 and t > int(state.get("eb", t)):
        clear_trade(state)
        state["flat"] = t
        d = 0

    if d == 0:
        if pos != 0:
            return {"target": 0.0, "stop": None, "take": None}
        flat_bar = int(state.get("flat", -10 ** 9))
        if t - flat_bar < 16:
            return {"target": 0.0, "stop": None, "take": None}
        if not (bull or bear):
            return {"target": 0.0, "stop": None, "take": None}
        h1 = hist.htf(60)
        if len(h1.close) < 1:
            return {"target": 0.0, "stop": None, "take": None}
        hc = h1.close
        e20 = ind.ema(hc, 20)
        hclose = float(hc[-1])
        hema = float(e20[-1])
        if not (math.isfinite(hclose) and math.isfinite(hema)):
            return {"target": 0.0, "stop": None, "take": None}
        atr = float(ind.atr(hist, 14)[-1])
        if not math.isfinite(atr) or atr <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        nd = 0
        if bull and hclose > hema:
            nd = 1
        elif bear and hclose < hema:
            nd = -1
        if nd == 0:
            return {"target": 0.0, "stop": None, "take": None}
        state["dir"] = nd
        state["entry"] = close
        state["eatr"] = atr
        state["last_add"] = close
        state["adds"] = 0
        state["eb"] = t
        stop = close - nd * 1.5 * atr
        return {"target": 0.25 * nd, "stop": stop, "take": None}

    # In trade
    entry = float(state["entry"])
    eatr = float(state["eatr"])
    stop = entry - d * 1.5 * eatr

    # Reverse MACD flip -> exit at next open
    if (d == 1 and bear) or (d == -1 and bull):
        return {"target": 0.0, "stop": stop, "take": None}

    target = pos
    adds = int(state.get("adds", 0))
    last_add = float(state.get("last_add", entry))
    if adds < 1 and pos != 0:
        if d * (close - last_add) >= 2.0 * eatr:
            newt = min(abs(pos) + 0.25, 1.0) * d
            target = newt
            state["adds"] = adds + 1
            state["last_add"] = close

    return {"target": target, "stop": stop, "take": None}

