def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    c = float(hist.close[-1])
    hi = float(hist.high[-1])
    lo = float(hist.low[-1])

    prior_high = float(ind.highest(hist.high, LOOKBACK)[-2])
    prior_low = float(ind.lowest(hist.low, LOOKBACK)[-2])
    atr = float(ind.atr(hist, 14)[-1])

    # 4h trend filter (completed candles only)
    h4 = hist.htf(240)
    ema4 = float("nan")
    if len(h4) > 0:
        ema4 = float(ind.ema(h4.close, EMA_LEN)[-1])
    filt_ok = not math.isnan(ema4)

    # Breakout detection (level condition, refreshes each bar it holds)
    if not math.isnan(prior_high) and c > prior_high:
        state["long_lvl"] = prior_high
        state["long_t"] = t
    if not math.isnan(prior_low) and c < prior_low:
        state["short_lvl"] = prior_low
        state["short_t"] = t

    # Expire stale breakouts
    if "long_t" in state and t - state["long_t"] > RETEST_WINDOW:
        del state["long_t"]
        del state["long_lvl"]
    if "short_t" in state and t - state["short_t"] > RETEST_WINDOW:
        del state["short_t"]
        del state["short_lvl"]

    # Retest signals
    long_sig = False
    if "long_t" in state and filt_ok:
        dt = t - state["long_t"]
        if 0 < dt <= RETEST_WINDOW and lo <= state["long_lvl"] and c > ema4:
            long_sig = True
    short_sig = False
    if "short_t" in state and filt_ok:
        dt = t - state["short_t"]
        if 0 < dt <= RETEST_WINDOW and hi >= state["short_lvl"] and c < ema4:
            short_sig = True

    # Manage open trade
    if "dir" in state:
        if pos == 0.0:
            # stopped out (or never filled)
            clear_trade(state)
        else:
            d = state["dir"]
            stop = state["stop"]
            if t - state["entry_t"] >= TIME_STOP:
                clear_trade(state)
                return {"target": 0.0, "stop": None, "take": None}
            if (d > 0 and short_sig) or (d < 0 and long_sig):
                clear_trade(state)
                return {"target": 0.0, "stop": None, "take": None}
            return {"target": pos, "stop": stop, "take": None}

    # Flat: look for entries
    if pos == 0.0 and not math.isnan(atr) and atr > 0:
        if long_sig:
            stop = c - STOP_ATR * atr
            state["dir"] = 1
            state["entry"] = c
            state["entry_atr"] = atr
            state["entry_t"] = t
            state["stop"] = stop
            del state["long_t"]
            del state["long_lvl"]
            return {"target": SIZE, "stop": stop, "take": None}
        if short_sig:
            stop = c + STOP_ATR * atr
            state["dir"] = -1
            state["entry"] = c
            state["entry_atr"] = atr
            state["entry_t"] = t
            state["stop"] = stop
            del state["short_t"]
            del state["short_lvl"]
            return {"target": -SIZE, "stop": stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np


def clear_trade(state):
    for k in ("dir", "entry", "atr", "ext", "k", "be", "size"):
        if k in state:
            del state[k]


def open_trade(state, d, close, atr, size):
    state["dir"] = d
    state["entry"] = close
    state["atr"] = atr
    state["ext"] = close
    state["k"] = 0
    state["be"] = False
    state["size"] = size


def compute_levels(state):
    d = state["dir"]
    e = state["entry"]
    a = state["atr"]
    k = state["k"]
    # moving box, ratcheted k times by 2 ATR
    box_stop = e + d * (2.0 * a * k - 2.0 * a)
    take = e + d * (2.0 * a * k + 2.0 * a)
    stop = box_stop
    if state["be"]:
        trail = state["ext"] - d * 1.5 * a
        if d > 0:
            stop = max(stop, e, trail)
        else:
            stop = min(stop, e, trail)
    return stop, take


def strategy(hist, state, pos, ind):
    close = hist.close[-1]
    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    # trade closed by stop/take
    if pos == 0.0 and "dir" in state:
        clear_trade(state)

    # signal
    sig = 0
    n = len(hist)
    if n > 97 and not math.isnan(atr) and atr > 0:
        hh = ind.highest(hist.high, 96)[-2]
        ll = ind.lowest(hist.low, 96)[-2]
        h4 = hist.htf(240)
        if len(h4) >= 1:
            ema4 = ind.ema(h4.close, 20)[-1]
            if not (math.isnan(hh) or math.isnan(ema4)):
                if close > hh and close > ema4:
                    sig = 1
                elif close < ll and close < ema4:
                    sig = -1

    size = 0.0
    if sig != 0:
        size = 0.01 * close / (3.0 * atr)
        size = min(1.0, max(0.05, size))

    if "dir" not in state:
        if sig != 0 and pos == 0.0:
            open_trade(state, sig, close, atr, size)
            stop, take = compute_levels(state)
            return {"target": sig * size, "stop": stop, "take": take}
        return {"target": 0.0 if pos == 0.0 else pos, "stop": None, "take": None}

    d = state["dir"]

    # opposite signal: flip
    if sig == -d:
        open_trade(state, sig, close, atr, size)
        stop, take = compute_levels(state)
        return {"target": sig * size, "stop": stop, "take": take}

    # manage live trade
    e = state["entry"]
    a = state["atr"]
    if d > 0:
        state["ext"] = max(state["ext"], hist.high[-1])
    else:
        state["ext"] = min(state["ext"], hist.low[-1])
    prof = (close - e) * d
    kk = int(math.floor(prof / (2.0 * a))) if a > 0 else 0
    if kk > state["k"]:
        state["k"] = kk
    if prof >= 0.5 * a:
        state["be"] = True

    stop, take = compute_levels(state)
    return {"target": pos, "stop": stop, "take": take}

