def htf_filter(hist, ind):
    h = hist.htf(60)
    if len(h) < 20:
        return False, False
    e = ind.ema(h.close, 20)
    c = h.close[-1]
    return bool(c > e[-1]), bool(c < e[-1])


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]
    atr = ind.atr(hist, 14)[-1]

    hh = ind.highest(hist.high, 48)
    ll = ind.lowest(hist.low, 48)
    prior_high = hh[-2] if len(hh) >= 2 else float("nan")
    prior_low = ll[-2] if len(ll) >= 2 else float("nan")

    bull_htf, bear_htf = htf_filter(hist, ind)

    # --- retest triggers using setups armed on earlier bars ---
    long_trigger = False
    if state.get("l_armed", False):
        at = state["l_t"]
        if at < t <= at + 16:
            if low <= state["l_lvl"] and bull_htf:
                long_trigger = True
        elif t > at + 16:
            state["l_armed"] = False

    short_trigger = False
    if state.get("s_armed", False):
        at = state["s_t"]
        if at < t <= at + 16:
            if high >= state["s_lvl"] and bear_htf:
                short_trigger = True
        elif t > at + 16:
            state["s_armed"] = False

    # --- arm setups (level condition) ---
    if not math.isnan(prior_high) and close > prior_high:
        state["l_armed"] = True
        state["l_t"] = t
        state["l_lvl"] = float(prior_high)
    if not math.isnan(prior_low) and close < prior_low:
        state["s_armed"] = True
        state["s_t"] = t
        state["s_lvl"] = float(prior_low)

    # --- detect trade closed by stop/take ---
    if state.get("in_trade", False) and pos <= 0:
        state["in_trade"] = False

    if state.get("in_trade", False):
        entry = state["entry"]
        eatr = state["eatr"]
        state["ext"] = max(state["ext"], float(high))
        if close >= entry + 2.0 * eatr:
            state["be"] = True

        # exits: HTF trend filter fails or short signal prints
        if (not bull_htf) or short_trigger:
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        target = pos
        if (not state.get("scaled", False)) and close >= entry + 1.5 * eatr:
            state["scaled"] = True
            target = pos / 2.0

        stop = state["ext"] - 1.5 * eatr
        if state.get("be", False):
            stop = max(stop, entry)
        return {"target": target, "stop": stop, "take": None}

    # --- flat: entry ---
    if pos == 0 and long_trigger and not math.isnan(atr) and atr > 0:
        state["in_trade"] = True
