    if d > 0:
        box_stop = e + (k * STEP_ATR - STOP_ATR) * a
        take = e + (k * STEP_ATR + TAKE_ATR) * a
        trail = ext - TRAIL_ATR * a
        stop = max(box_stop, trail)
    else:
        box_stop = e - (k * STEP_ATR - STOP_ATR) * a
        take = e - (k * STEP_ATR + TAKE_ATR) * a
        trail = ext + TRAIL_ATR * a
        stop = min(box_stop, trail)
    return stop, take


