    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]
    atr = ind.atr(hist, 14)[-1]

    # detect trade end (stop/take filled)
    if "dir" in state and t > state["entry_t"] and pos == 0.0:
        clear_trade(state)

    # ---- retest triggers on existing arms (armed on earlier bars)
    long_sig = False
    short_sig = False
    if "armL_lvl" in state:
        if t - state["armL_t"] > ARM_BARS:
            del state["armL_lvl"]
            del state["armL_t"]
        elif low <= state["armL_lvl"]:
            long_sig = True
            del state["armL_lvl"]
            del state["armL_t"]
    if "armS_lvl" in state:
        if t - state["armS_t"] > ARM_BARS:
            del state["armS_lvl"]
            del state["armS_t"]
        elif high >= state["armS_lvl"]:
            short_sig = True
            del state["armS_lvl"]
            del state["armS_t"]

    # ---- arm on new breakouts
    if t >= LOOKBACK:
        ph = ind.highest(hist.high, LOOKBACK)[-2]
        pl = ind.lowest(hist.low, LOOKBACK)[-2]
        if not math.isnan(ph) and high > ph:
