            state["armL_t"] = t
        if not math.isnan(pl) and low < pl:
            state["armS_lvl"] = float(pl)
            state["armS_t"] = t

    if long_sig and short_sig:
        long_sig = False
        short_sig = False

    cur_dir = state.get("dir", 0)
    new_dir = 0
    if long_sig and cur_dir <= 0:
        new_dir = 1
    elif short_sig and cur_dir >= 0:
        new_dir = -1

    if new_dir != 0 and atr > 0 and not math.isnan(atr):
        clear_trade(state)
        state["dir"] = new_dir
        state["entry"] = float(close)
        state["eatr"] = float(atr)
        state["steps"] = 0
        state["ext"] = float(high) if new_dir > 0 else float(low)
        state["entry_t"] = t
