        stop, take = levels(state)
        return {"target": new_dir * size, "stop": stop, "take": take}

    if "dir" in state:
        d = state["dir"]
        e = state["entry"]
        a = state["eatr"]
        if d > 0:
            if high > state["ext"]:
                state["ext"] = float(high)
            k = int(math.floor((close - e) / (STEP_ATR * a) + 1e-12))
        else:
            if low < state["ext"]:
                state["ext"] = float(low)
            k = int(math.floor((e - close) / (STEP_ATR * a) + 1e-12))
        if k > state["steps"]:
            state["steps"] = k
        stop, take = levels(state)
        return {"target": pos, "stop": stop, "take": take}

    return {"target": pos if pos != 0.0 else 0.0, "stop": None, "take": None}

