    m0, s0 = macd_line[-1], signal_line[-1]
    m1, s1 = macd_line[-2], signal_line[-2]
    valid = not (math.isnan(m0) or math.isnan(s0) or math.isnan(m1) or math.isnan(s1))
    cross_up = valid and (m1 <= s1) and (m0 > s0)
    cross_dn = valid and (m1 >= s1) and (m0 < s0)

    atr = ind.atr(hist, 14)
    a = float(atr[-1])

    # Detect a trade that has ended (stop fill or executed exit)
    if state.get("in_trade", False) and pos <= 0 and t > state.get("entry_t", t):
        clear_trade(state)

    if state.get("in_trade", False):
        entry_px = state["entry_px"]
        entry_atr = state["entry_atr"]
        entry_t = state["entry_t"]

        # Breakeven activation (evaluated on closes, inclusive)
        if not state.get("be", False) and c - entry_px >= 1.5 * entry_atr:
