                state["adds"] = state.get("adds", 0) + 1
                state["last_add"] = c
        return {"target": target, "stop": stop, "take": None}

    # Flat: look for entry
    if pos == 0 and cross_up and not math.isnan(a) and a > 0:
        state["in_trade"] = True
        state["entry_t"] = t
        state["entry_px"] = c
        state["entry_atr"] = a
        state["last_add"] = c
        state["adds"] = 0
        state["be"] = False
        return {"target": 0.25, "stop": None, "take": None}

    return {"target": pos if pos == 0 else 0.0, "stop": None, "take": None}

import math
import numpy as np

COOLDOWN_BARS = 48      # 12 hours of 15m bars
MAX_HOLD_BARS = 256     # 64 hours of 15m bars
RISK = 0.005
ATR_MULT = 1.0
CAP = 1.0
FLOOR = 0.05
DAY_MS = 86400000


def strategy(hist, state, pos, ind) -> dict:
    t = len(hist) - 1
    close = hist.close
    macd_line, signal_line, _ = ind.macd(close, 8, 17, 9)

    m0, m1 = macd_line[-1], macd_line[-2]
    s0, s1 = signal_line[-1], signal_line[-2]
    valid = not (np.isnan(m0) or np.isnan(m1) or np.isnan(s0) or np.isnan(s1))
    bull_cross = valid and (m1 <= s1) and (m0 > s0)
    bear_cross = valid and (m1 >= s1) and (m0 < s0)

    if state.get("in_trade", False):
        if pos == 0.0:
            # position closed externally; mark flat now
            state["in_trade"] = False
            state["last_exit"] = t
        else:
            entry_bar = state.get("entry_bar", t)
            if bear_cross or (t - entry_bar) >= MAX_HOLD_BARS:
                state["in_trade"] = False
                state["last_exit"] = t
                return {"target": 0.0, "stop": None, "take": None}
            return {"target": pos, "stop": None, "take": None}

    # flat
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    if not bull_cross:
        return {"target": 0.0, "stop": None, "take": None}

    if "last_exit" in state and (t - state["last_exit"]) < COOLDOWN_BARS:
        return {"target": 0.0, "stop": None, "take": None}

    day = int(hist.time[-1] // DAY_MS)
    if "last_entry_day" in state and state["last_entry_day"] == day:
        return {"target": 0.0, "stop": None, "take": None}

    atr = ind.atr(hist, 14)[-1]
    c = close[-1]
    if atr is None or np.isnan(atr) or atr <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    size = RISK * c / (ATR_MULT * atr)
    size = max(FLOOR, min(CAP, size))

    state["in_trade"] = True
    state["entry_bar"] = t
    state["entry_price"] = float(c)
    state["entry_atr"] = float(atr)
    state["last_entry_day"] = day
    return {"target": float(size), "stop": None, "take": None}

