def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    c = float(hist.close[-1])
    hi = float(hist.high[-1])
    lo = float(hist.low[-1])

    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    # Box from the prior 32 bars (excluding current bar)
    box_hi = float(ind.highest(hist.high, BOX_N)[-2])
    box_lo = float(ind.lowest(hist.low, BOX_N)[-2])

    # 1h EMA filter on last completed 1h candle
    h1 = hist.htf(60)
    up = False
    down = False
    if len(h1) >= 1:
        h1c = h1.close
        e20 = ind.ema(h1c, 20)
        lc = float(h1c[-1])
        le = float(e20[-1])
        if not (math.isnan(lc) or math.isnan(le)):
            up = lc > le
            down = lc < le

    long_sig = False
    short_sig = False
    if not (math.isnan(atr) or math.isnan(box_hi) or math.isnan(box_lo)) and atr > 0:
        box_ok = (box_hi - box_lo) <= MAX_BOX_ATR * atr
        long_sig = box_ok and up and c > box_hi
        short_sig = box_ok and down and c < box_lo

    # Trade closed (stop fill or exit executed)
    if pos == 0 and "dir" in state and t > state["entry_t"]:
        clear_trade(state)

    # Manage open trade
    if pos != 0:
        if "dir" not in state:
            return {"target": 0.0, "stop": None, "take": None}
        d = state["dir"]
        entry = state["entry"]
        eatr = state["eatr"]

        if d > 0:
            state["ext"] = max(state["ext"], hi)
        else:
            state["ext"] = min(state["ext"], lo)

        if d * (c - entry) >= BE_TRIGGER_ATR * eatr:
            state["trail"] = True

        stop = None
        if state.get("trail", False):
            if d > 0:
                stop = max(entry, state["ext"] - TRAIL_ATR * eatr)
            else:
                stop = min(entry, state["ext"] + TRAIL_ATR * eatr)

        if t - state["entry_t"] >= MAX_HOLD:
            return {"target": 0.0, "stop": stop, "take": None}
        if (d > 0 and short_sig) or (d < 0 and long_sig):
            return {"target": 0.0, "stop": stop, "take": None}

        return {"target": pos, "stop": stop, "take": None}

    # Flat: look for entries
    if long_sig or short_sig:
        d = 1 if long_sig else -1
        state["dir"] = d
        state["entry"] = c
        state["eatr"] = atr
        state["entry_t"] = t
        state["ext"] = hi if d > 0 else lo
        state["trail"] = False
        return {"target": SIZE * d, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

