            if state["be"]:
                stop = min(stop, entry)
            take = entry - TAKE_ATR * eatr

        target = pos if pos != 0.0 else d * SIZE
        return {"target": target, "stop": stop, "take": take}

    # Flat: look for entries
    if pos == 0.0 and not math.isnan(atr) and atr > 0:
