    rsi = ind.rsi(close, RSI_LEN)
    r_now = float(rsi[-1])
    r_prev = float(rsi[-2])
    valid = not (math.isnan(r_now) or math.isnan(r_prev))
    long_sig = valid and r_prev <= 30.0 and r_now > 30.0
    short_sig = valid and r_prev >= 70.0 and r_now < 70.0

    if pos == 0:
        # resolve state of a trade that has ended
        if state.get("exiting", False):
            state["cd_start"] = t
            state["exiting"] = False
            state["dir"] = 0
        elif state.get("dir", 0) != 0:
            # stopped out (no cooldown)
            state["dir"] = 0

        if "cd_start" in state and t - int(state["cd_start"]) < COOLDOWN:
            return {"target": 0.0, "stop": None, "take": None}

        atr = ind.atr(hist, 14)
        a = float(atr[-1])
        if math.isnan(a) or a <= 0:
            return {"target": 0.0, "stop": None, "take": None}

        if long_sig:
            stop = c - STOP_MULT * a
            state["dir"] = 1
