        if short_sig:
            stop = c + STOP_MULT * a
            state["dir"] = -1
            state["stop"] = stop
            state["exiting"] = False
            return {"target": -1.0, "stop": stop, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # in a position
    d = int(state.get("dir", 1 if pos > 0 else -1))
    if d == 0:
        d = 1 if pos > 0 else -1
        state["dir"] = d
    stop = state.get("stop", None)
    if stop is None:
        a = float(ind.atr(hist, 14)[-1])
        stop = c - STOP_MULT * a if d > 0 else c + STOP_MULT * a
        state["stop"] = stop
    stop = float(stop)

    if state.get("exiting", False):
        return {"target": 0.0, "stop": stop, "take": None}

    if (d > 0 and short_sig) or (d < 0 and long_sig):
        state["exiting"] = True
        return {"target": 0.0, "stop": stop, "take": None}

