    valid = not (math.isnan(m0) or math.isnan(s0) or math.isnan(m1) or math.isnan(s1))
    cross_up = valid and (m1 <= s1) and (m0 > s0)
    cross_dn = valid and (m1 >= s1) and (m0 < s0)

    in_trade = state.get("in_trade", False)

    # Detect stop fill (position went flat while trade live)
    if in_trade and pos == 0.0 and t > state.get("entry_t", t):
        state["in_trade"] = False
        state["exit_t"] = t
        in_trade = False

    if in_trade:
        d = state["dir"]
        entry = state["entry"]
        eatr = state["eatr"]

        # Opposite cross bails out
        if (d > 0 and cross_dn) or (d < 0 and cross_up):
            state["in_trade"] = False
            state["exit_t"] = t + 1
            return {"target": 0.0, "stop": None, "take": None}

        # Breakeven once a close is at least 2 ATR in profit
        if not state.get("be", False):
            if (d > 0 and c >= entry + 2.0 * eatr) or (d < 0 and c <= entry - 2.0 * eatr):
                state["be"] = True

        # Pyramiding: up to two adds, +0.5 each, when 1 ATR in favor from last add
        size = state["size"]
        adds = state.get("adds", 0)
        last_add = state["last_add"]
        if adds < 2:
            if (d > 0 and c >= last_add + eatr) or (d < 0 and c <= last_add - eatr):
                size = min(1.0, size + 0.5)
                adds += 1
                state["adds"] = adds
                state["size"] = size
                state["last_add"] = c

        stop = entry if state.get("be", False) else None
        return {"target": d * size, "stop": stop, "take": None}

    # Flat: look for entries
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    if "exit_t" in state and t - state["exit_t"] < 48:
        return {"target": 0.0, "stop": None, "take": None}
    if state.get("last_entry_day", -1) == day:
        return {"target": 0.0, "stop": None, "take": None}

    if not (cross_up or cross_dn):
        return {"target": 0.0, "stop": None, "take": None}

    h1 = hist.htf(60)
    if len(h1) < 20:
        return {"target": 0.0, "stop": None, "take": None}
    ema20 = ind.ema(h1.close, 20)
    hc = float(h1.close[-1])
    he = float(ema20[-1])
    if math.isnan(he):
        return {"target": 0.0, "stop": None, "take": None}

    atr = float(ind.atr(hist, 14)[-1])
    if math.isnan(atr) or atr <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    d = 0
    if cross_up and hc > he:
        d = 1
    elif cross_dn and hc < he:
        d = -1
    if d == 0:
        return {"target": 0.0, "stop": None, "take": None}

    state["in_trade"] = True
    state["dir"] = d
    state["entry"] = c
    state["eatr"] = atr
    state["entry_t"] = t
    state["size"] = 0.5
    state["adds"] = 0
    state["last_add"] = c
    state["be"] = False
    state["last_entry_day"] = day
    return {"target": d * 0.5, "stop": None, "take": None}

