            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    atr = ind.atr(hist, 14)[-1]
    upper = ind.highest(hist.high, DON_N)[-2]
    lower = ind.lowest(hist.low, DON_N)[-2]

    h1 = hist.htf(60)
    trend_up = False
    trend_dn = False
    if len(h1.close) >= 1:
        e = ind.ema(h1.close, EMA_N)[-1]
        c1 = h1.close[-1]
        if not (math.isnan(e) or math.isnan(c1)):
            trend_up = c1 > e
            trend_dn = c1 < e

    long_sig = (not math.isnan(upper)) and close > upper and trend_up
    short_sig = (not math.isnan(lower)) and close < lower and trend_dn

    # detect trade closed by stop/take
    if state.get("in_trade", False) and pos == 0.0 and t > state.get("et", t):
        clear_trade(state)

    if state.get("in_trade", False):
        d = state["dir"]
        entry = state["entry"]
        eatr = state["eatr"]
        et = state["et"]
        ext = state["ext"]

        if t > et:
            if d > 0:
                ext = max(ext, high)
            else:
                ext = min(ext, low)
            state["ext"] = ext

        if d > 0 and close >= entry + BE_ATR * eatr:
            state["be"] = True
        if d < 0 and close <= entry - BE_ATR * eatr:
            state["be"] = True

        if d > 0:
            stop = ext - TRAIL_ATR * eatr
            if state.get("be", False):
                stop = max(stop, entry)
        else:
            stop = ext + TRAIL_ATR * eatr
            if state.get("be", False):
                stop = min(stop, entry)

        exit_now = False
        if t - et >= TIME_BARS:
            exit_now = True
        if d > 0 and short_sig:
            exit_now = True
        if d < 0 and long_sig:
            exit_now = True

        if exit_now:
            clear_trade(state)
            return {"target": 0.0, "stop": stop, "take": None}

        tgt = pos if pos != 0.0 else state.get("size", 0.0)
        return {"target": tgt, "stop": stop, "take": None}

    # flat: look for entries
    if pos == 0.0 and atr > 0 and not math.isnan(atr):
        d = 0
        if long_sig:
            d = 1
        elif short_sig:
            d = -1
        if d != 0:
            size = RISK * close / (RISK_ATR * atr)
            size = min(CAP, max(FLOOR, size))
            state["in_trade"] = True
            state["dir"] = d
            state["entry"] = float(close)
            state["eatr"] = float(atr)
            state["et"] = t
            state["ext"] = float(close)
            state["be"] = False
            state["size"] = float(d * size)
            if d > 0:
                stop = close - TRAIL_ATR * atr
            else:
                stop = close + TRAIL_ATR * atr
            return {"target": d * size, "stop": stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

