import numpy as np

SIZE = 0.75
LOOKBACK = 20
PROFIT_ATR = 2.0


def strategy(hist, state, pos, ind):
    close = hist.close
    c = float(close[-1])
    n = len(hist)
    out = {"target": pos, "stop": None, "take": None}

    if n < LOOKBACK + 2:
        return out

    hh = ind.highest(hist.high, LOOKBACK)
    ll = ind.lowest(hist.low, LOOKBACK)
    prior_high = float(hh[-2])
    prior_low = float(ll[-2])
    if math.isnan(prior_high) or math.isnan(prior_low):
        return out

    long_sig = c > prior_high
    short_sig = c < prior_low

    atr = ind.atr(hist, 14)
    a = float(atr[-1])

    if abs(pos) < 1e-9:
        # flat: clear any old trade state
        for k in ("side", "entry", "eatr", "partial"):
            if k in state:
                del state[k]
        if math.isnan(a) or a <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        if long_sig:
            state["side"] = 1
            state["entry"] = c
            state["eatr"] = a
            state["partial"] = False
            return {"target": SIZE, "stop": None, "take": None}
        if short_sig:
            state["side"] = -1
            state["entry"] = c
            state["eatr"] = a
            state["partial"] = False
            return {"target": -SIZE, "stop": None, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # in a trade
    side = 1 if pos > 0 else -1
    if "side" not in state or int(state["side"]) != side:
        # recover state if missing/inconsistent
        state["side"] = side
        state["entry"] = c
        state["eatr"] = a if not math.isnan(a) else 0.0
        state["partial"] = False

    entry = float(state["entry"])
    eatr = float(state["eatr"])
    partial = bool(state.get("partial", False))

    # opposite signal -> close the position
    if (side > 0 and short_sig) or (side < 0 and long_sig):
        return {"target": 0.0, "stop": None, "take": None}

    target = pos
    if not partial and eatr > 0:
        profit = (c - entry) * side
        if profit >= PROFIT_ATR * eatr:
            state["partial"] = True
            target = side * SIZE / 2.0

    return {"target": target, "stop": None, "take": None}

import math
import numpy as np

DON_N = 20
SIZE = 0.75
MAX_ENTRIES_PER_DAY = 3
STOP_ATR = 1.0
TAKE_ATR = 2.0
RATCHET_ATR = 2.0
BE_ATR = 1.5
DAY_MS = 86400000


def clear_trade(state):
    for k in ("in_trade", "entry", "eatr", "anchor", "be"):
        if k in state:
            del state[k]


def box_levels(state):
    entry = state["entry"]
    eatr = state["eatr"]
    anchor = state["anchor"]
    stop = anchor - STOP_ATR * eatr
    if state.get("be", False):
        stop = max(stop, entry)
    take = anchor + TAKE_ATR * eatr
    return stop, take


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = float(hist.close[-1])

    # Daily entry counter (UTC day of the current bar)
    day = int(hist.time[-1] // DAY_MS)
    if state.get("day", -1) != day:
        state["day"] = day
        state["entries"] = 0

    # Prior 20-bar channel (bars before the current one)
    if t < DON_N:
        return {"target": pos, "stop": None, "take": None}
    prior_high = float(np.max(hist.high[-DON_N - 1:-1]))
    prior_low = float(np.min(hist.low[-DON_N - 1:-1]))

    # Trade closed by a stop/take fill
    if state.get("in_trade", False) and pos == 0.0:
        clear_trade(state)

    if state.get("in_trade", False):
        # Bearish 20-bar breakdown -> flat
        if close < prior_low:
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        entry = state["entry"]
        eatr = state["eatr"]

        # Ratchet the whole box up by 2 ATR for each further 2 ATR close past the anchor
        if eatr > 0:
            while close >= state["anchor"] + RATCHET_ATR * eatr:
                state["anchor"] = state["anchor"] + RATCHET_ATR * eatr

        # Permanent breakeven once a close is 1.5 ATR in profit
        if close >= entry + BE_ATR * eatr:
            state["be"] = True

        stop, take = box_levels(state)
        return {"target": pos, "stop": stop, "take": take}

    # Flat: look for an entry
    if pos == 0.0:
        if close > prior_high and state.get("entries", 0) < MAX_ENTRIES_PER_DAY:
            atr = float(ind.atr(hist, 14)[-1])
            if not math.isnan(atr) and atr > 0:
                state["in_trade"] = True
                state["entry"] = close
                state["eatr"] = atr
                state["anchor"] = close
                state["be"] = False
                state["entries"] = state.get("entries", 0) + 1
                stop, take = box_levels(state)
                return {"target": SIZE, "stop": stop, "take": take}
        return {"target": 0.0, "stop": None, "take": None}

    # Position without tracked trade state (should not happen): flatten
    return {"target": 0.0, "stop": None, "take": None}

