        if (d > 0 and short_sig) or (d < 0 and long_sig):
            clear_trade(state)
            return {"target": 0.0, "stop": stop, "take": take}

        size = state["size"]
        adds = state["adds"]
        last_add = state["last_add"]
        if adds < 2:
            if (d > 0 and c >= last_add + 2.0 * ea) or (d < 0 and c <= last_add - 2.0 * ea):
                size = min(1.0, size + 0.5)
                state["size"] = size
                state["adds"] = adds + 1
                state["last_add"] = c
        return {"target": d * size, "stop": stop, "take": take}

    # Flat: look for entries
    if math.isnan(a_now) or a_now <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    if long_sig or short_sig:
        d = 1 if long_sig else -1
        state["dir"] = d
        state["entry"] = float(c)
        state["atr"] = float(a_now)
        state["last_add"] = float(c)
        state["adds"] = 0
        state["size"] = 0.5
        if d > 0:
            stop = c - 2.0 * a_now
            take = c + 6.0 * a_now
        else:
            stop = c + 2.0 * a_now
            take = c - 6.0 * a_now
        return {"target": d * 0.5, "stop": float(stop), "take": float(take)}

    return {"target": 0.0, "stop": None, "take": None}

import math
import numpy as np

LOOKBACK = 48
ARM_BARS = 8
SIZE = 0.75
STOP_ATR = 1.0
TAKE_ATR = 4.0
SCALE_ATR = 1.5


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    high = hist.high
    low = hist.low
    c = float(close[-1])
    lo = float(low[-1])
    hi = float(high[-1])

    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    # Prior 48-bar high/low (bars before the current one)
    prior_high = float(np.max(high[-LOOKBACK - 1:-1]))
    prior_low = float(np.min(low[-LOOKBACK - 1:-1]))

    # ---- detect the trade having ended (stop/take fill or flatten executed) ----
    if state.get("in_trade", False):
        if pos == 0.0 and t > state.get("entry_bar", t):
            state["in_trade"] = False
            state["scaled"] = False

    # ---- retest signals using setups armed on PREVIOUS bars ----
    long_sig = False
    short_sig = False
    if "bull_level" in state:
        if state["bull_arm_bar"] < t <= state["bull_exp"]:
            if lo <= state["bull_level"]:
                long_sig = True
    if "bear_level" in state:
        if state["bear_arm_bar"] < t <= state["bear_exp"]:
            if hi >= state["bear_level"]:
                short_sig = True
    if long_sig and short_sig:
        long_sig = False
        short_sig = False

    # consume triggered setups
    if long_sig:
        del state["bull_level"]
    if short_sig:
        del state["bear_level"]

    # ---- arm new setups from this bar's breakout (newer replaces older) ----
    if not math.isnan(prior_high) and c > prior_high:
        state["bull_level"] = prior_high
        state["bull_arm_bar"] = t
        state["bull_exp"] = t + ARM_BARS
    if not math.isnan(prior_low) and c < prior_low:
        state["bear_level"] = prior_low
        state["bear_arm_bar"] = t
        state["bear_exp"] = t + ARM_BARS

    # ---- manage open trade ----
    if state.get("in_trade", False):
        d = state["dir"]
        entry = state["entry"]
        ea = state["entry_atr"]
        if d > 0:
            stop = entry - STOP_ATR * ea
            take = entry + TAKE_ATR * ea
        else:
            stop = entry + STOP_ATR * ea
            take = entry - TAKE_ATR * ea

        # opposite signal -> flatten
        if (d > 0 and short_sig) or (d < 0 and long_sig):
            return {"target": 0.0, "stop": None, "take": None}

        target = pos
        if not state.get("scaled", False) and pos != 0.0:
            if (d > 0 and c >= entry + SCALE_ATR * ea) or \
               (d < 0 and c <= entry - SCALE_ATR * ea):
                target = d * SIZE / 2.0
                state["scaled"] = True
        elif state.get("scaled", False):
            target = d * SIZE / 2.0
        if pos == 0.0 and not state.get("scaled", False):
            # entry order still pending fill
            target = d * SIZE
        return {"target": target, "stop": stop, "take": take}

    # ---- flat: new entries ----
    if pos == 0.0 and not math.isnan(atr) and atr > 0:
        if long_sig:
            state["in_trade"] = True
            state["dir"] = 1
            state["entry"] = c
            state["entry_atr"] = atr
            state["entry_bar"] = t
            state["scaled"] = False
            return {"target": SIZE, "stop": c - STOP_ATR * atr,
                    "take": c + TAKE_ATR * atr}
        if short_sig:
            state["in_trade"] = True
            state["dir"] = -1
            state["entry"] = c
            state["entry_atr"] = atr
            state["entry_bar"] = t
            state["scaled"] = False
            return {"target": -SIZE, "stop": c + STOP_ATR * atr,
                    "take": c - TAKE_ATR * atr}

    return {"target": 0.0 if pos == 0.0 else pos, "stop": None, "take": None}

import math
import numpy as np

UNIT = 0.25
MAX_ADDS = 1
CAP = 1.0
LOOKBACK = 48
ARM_BARS = 32
STOP_ATR = 2.0
TAKE_ATR = 2.0
TRAIL_ATR = 4.0
ADD_ATR = 2.0


def reset_trade(state):
    for k in ("dir", "ep", "eatr", "last", "adds", "ext", "et", "tgt"):
        if k in state:
            del state[k]


def levels(state):
    d = state["dir"]
    ep = state["ep"]
    ea = state["eatr"]
    ext = state["ext"]
    if d > 0:
        hard = ep - STOP_ATR * ea
        trail = ext - TRAIL_ATR * ea
        stop = max(hard, trail)
        take = ep + TAKE_ATR * ea
    else:
        hard = ep + STOP_ATR * ea
        trail = ext + TRAIL_ATR * ea
        stop = min(hard, trail)
        take = ep - TAKE_ATR * ea
    return stop, take


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    c = float(hist.close[-1])
    h = float(hist.high[-1])
    l = float(hist.low[-1])
    atr = float(ind.atr(hist, 14)[-1])
    hh = float(ind.highest(hist.high, LOOKBACK)[-2])
    ll = float(ind.lowest(hist.low, LOOKBACK)[-2])

    # retest signals from previously armed setups
    long_sig = False
    short_sig = False
    if "la_t" in state:
        lt = state["la_t"]
        if t > lt and t <= lt + ARM_BARS and l <= state["la_lvl"]:
            long_sig = True
        if t > lt + ARM_BARS:
            del state["la_t"]
            del state["la_lvl"]
    if "sa_t" in state:
        st = state["sa_t"]
        if t > st and t <= st + ARM_BARS and h >= state["sa_lvl"]:
            short_sig = True
        if t > st + ARM_BARS:
            del state["sa_t"]
            del state["sa_lvl"]

    # arm (level conditions, re-armed every bar beyond the level)
    if not math.isnan(hh) and c > hh:
        state["la_lvl"] = hh
        state["la_t"] = t
    if not math.isnan(ll) and c < ll:
        state["sa_lvl"] = ll
        state["sa_t"] = t

    d = state.get("dir", 0)
    # detect trade closed by stop/take
    if d != 0 and abs(pos) < 1e-9 and t > state["et"]:
        reset_trade(state)
        d = 0

    if d == 0:
        if math.isnan(atr) or atr <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        nd = 0
        if long_sig and not short_sig:
            nd = 1
        elif short_sig and not long_sig:
            nd = -1
        if nd != 0:
            state["dir"] = nd
            state["ep"] = c
            state["eatr"] = atr
            state["last"] = c
            state["adds"] = 0
            state["ext"] = c
            state["et"] = t
            state["tgt"] = UNIT * nd
            if nd > 0:
                if "la_t" in state:
                    del state["la_t"]
                    del state["la_lvl"]
            else:
                if "sa_t" in state:
                    del state["sa_t"]
                    del state["sa_lvl"]
            stop, take = levels(state)
            return {"target": UNIT * nd, "stop": stop, "take": take}
        return {"target": 0.0, "stop": None, "take": None}

    # in a trade
    if d > 0:
        state["ext"] = max(state["ext"], h)
    else:
        state["ext"] = min(state["ext"], l)

    if (d > 0 and short_sig) or (d < 0 and long_sig):
        reset_trade(state)
        return {"target": 0.0, "stop": None, "take": None}

    tgt = state["tgt"]
    ea = state["eatr"]
    if state["adds"] < MAX_ADDS and d * (c - state["last"]) >= ADD_ATR * ea:
        nt = abs(tgt) + UNIT
        if nt > CAP:
            nt = CAP
        if nt > abs(tgt) + 1e-9:
            tgt = nt * d
            state["tgt"] = tgt
            state["last"] = c
            state["adds"] = state["adds"] + 1

    stop, take = levels(state)
    return {"target": tgt, "stop": stop, "take": take}

import math
import numpy as np


def clear_trade(state):
    for k in ("dir", "eatr", "ext", "ref", "adds", "size"):
        if k in state:
            del state[k]


def open_trade(state, d, c, atr):
    state["dir"] = d
    state["eatr"] = float(atr)
    state["ext"] = float(c)
    state["ref"] = float(c)
    state["adds"] = 0
    state["size"] = 0.5


def strategy(hist, state, pos, ind):
    c = float(hist.close[-1])
    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    hh = float(ind.highest(hist.high, 32)[-2])
    ll = float(ind.lowest(hist.low, 32)[-2])
    valid = (not math.isnan(hh)) and (not math.isnan(ll)) and (not math.isnan(atr)) \
        and atr > 0 and (hh - ll) <= 6.0 * atr
    long_bo = valid and c > hh
    short_bo = valid and c < ll

    long_ok = False
    short_ok = False
    h4 = hist.htf(240)
    if len(h4) >= 20:
        e = float(ind.ema(h4.close, 20)[-1])
        hc = float(h4.close[-1])
        long_ok = hc > e
        short_ok = hc < e

    d = int(state.get("dir", 0))

    # stopped out / position gone
    if d != 0 and abs(pos) < 1e-9:
        clear_trade(state)
        d = 0

    if d == 0:
        if long_bo and long_ok:
            open_trade(state, 1, c, atr)
            return {"target": 0.5, "stop": c - 3.0 * atr, "take": None}
        if short_bo and short_ok:
            open_trade(state, -1, c, atr)
            return {"target": -0.5, "stop": c + 3.0 * atr, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    eatr = float(state["eatr"])
    ext = float(state["ext"])
    size = float(state.get("size", abs(pos)))

    if d == 1:
        ext = max(ext, float(hist.high[-1]))
        state["ext"] = ext
        if short_bo:
            if short_ok:
                open_trade(state, -1, c, atr)
                return {"target": -0.5, "stop": c + 3.0 * atr, "take": None}
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}
        adds = int(state.get("adds", 0))
        if adds < 2 and size < 1.0 and c >= float(state["ref"]) + 2.0 * eatr:
            size = min(1.0, size + 0.25)
            state["size"] = size
            state["adds"] = adds + 1
            state["ref"] = c
        return {"target": size, "stop": ext - 3.0 * eatr, "take": None}
    else:
        ext = min(ext, float(hist.low[-1]))
        state["ext"] = ext
        if long_bo:
            if long_ok:
                open_trade(state, 1, c, atr)
                return {"target": 0.5, "stop": c - 3.0 * atr, "take": None}
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}
        adds = int(state.get("adds", 0))
        if adds < 2 and size < 1.0 and c <= float(state["ref"]) - 2.0 * eatr:
            size = min(1.0, size + 0.25)
            state["size"] = size
            state["adds"] = adds + 1
            state["ref"] = c
        return {"target": -size, "stop": ext + 3.0 * eatr, "take": None}

import math
import numpy as np

BOX_N = 16
MAX_BOX_ATR = 6.0
SIZE = 0.75
COOLDOWN = 48


def grid(x):
    return math.floor(abs(x) / 0.05 + 0.5) * 0.05


def clear_trade(state):
    for k in ("in_trade", "dir", "entry", "eatr", "be", "scaled", "pending"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])
    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    # Box signal from the prior 16 bars (excluding current bar)
    sig = 0
    if t >= BOX_N + 1 and not math.isnan(atr) and atr > 0:
        hh = ind.highest(hist.high, BOX_N)
        ll = ind.lowest(hist.low, BOX_N)
        box_hi = float(hh[-2])
        box_lo = float(ll[-2])
        if not (math.isnan(box_hi) or math.isnan(box_lo)):
            if box_hi - box_lo <= MAX_BOX_ATR * atr:
                if c > box_hi:
                    sig = 1
                elif c < box_lo:
                    sig = -1

    # Track trade lifecycle
    if state.get("in_trade", False):
        if state.get("pending", False):
            if pos != 0.0:
                state["pending"] = False
        if not state.get("pending", False) and pos == 0.0:
            # closed by stop fill on this bar
            clear_trade(state)
            state["end_bar"] = t

    if state.get("in_trade", False):
        d = int(state["dir"])
        entry = float(state["entry"])
        eatr = float(state["eatr"])

        # opposite signal -> close at next open
        if sig == -d:
            clear_trade(state)
            state["end_bar"] = t + 1
            return {"target": 0.0, "stop": None, "take": None}

        profit = (c - entry) * d
        if profit >= 1.0 * eatr:
            state["be"] = True
        if profit >= 3.0 * eatr:
            state["scaled"] = True

        stop = entry if state.get("be", False) else None
        if state.get("scaled", False):
            target = d * grid(SIZE / 2.0)
        else:
            target = d * SIZE
        return {"target": target, "stop": stop, "take": None}

    # Flat: check cooldown and entry
    if pos != 0.0:
        # unexpected position without trade state; flatten
        return {"target": 0.0, "stop": None, "take": None}

    end_bar = state.get("end_bar", -10 ** 9)
    if t - end_bar < COOLDOWN:
        return {"target": 0.0, "stop": None, "take": None}

    if sig != 0:
        state["in_trade"] = True
        state["pending"] = True
        state["dir"] = sig
        state["entry"] = c
        state["eatr"] = atr
        state["be"] = False
        state["scaled"] = False
        return {"target": sig * SIZE, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

import math
import numpy as np


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    atr = ind.atr(hist, 14)[-1]
    hh = ind.highest(hist.high, 48)
    ll = ind.lowest(hist.low, 48)
    prior_hi = hh[-2]
    prior_lo = ll[-2]

    # 4h filter
    h4 = hist.htf(240)
    f_up = False
    f_dn = False
    if len(h4) >= 20:
        e = ind.ema(h4.close, 20)[-1]
        c4 = h4.close[-1]
        if not math.isnan(e):
            f_up = c4 > e
            f_dn = c4 < e

    d = state.get("dir", 0)

    # detect stop-out
    if d != 0 and pos == 0.0:
        state["dir"] = 0
        state["flat_t"] = t
        d = 0

    # retest checks using stored breakout info (from prior bars)
    retest_up = False
    retest_dn = False
    if "up_bar" in state:
        k = t - state["up_bar"]
        lvl = state["up_lvl"]
        if 1 <= k <= 8:
            if low <= lvl <= high:
                retest_up = True
                del state["up_bar"]
                del state["up_lvl"]
        elif k > 8:
            del state["up_bar"]
            del state["up_lvl"]
    if "dn_bar" in state:
        k = t - state["dn_bar"]
        lvl = state["dn_lvl"]
        if 1 <= k <= 8:
            if low <= lvl <= high:
                retest_dn = True
                del state["dn_bar"]
                del state["dn_lvl"]
        elif k > 8:
            del state["dn_bar"]
            del state["dn_lvl"]

    # update breakouts (level condition)
    if not math.isnan(prior_hi) and close > prior_hi:
        state["up_bar"] = t
        state["up_lvl"] = float(prior_hi)
    if not math.isnan(prior_lo) and close < prior_lo:
        state["dn_bar"] = t
        state["dn_lvl"] = float(prior_lo)

    long_sig = retest_up and f_up
    short_sig = retest_dn and f_dn
    if long_sig and short_sig:
        long_sig = False
        short_sig = False

    valid_atr = not math.isnan(atr) and atr > 0

    new_dir = 0
    if d == 0:
        cooled = ("flat_t" not in state) or (t - state["flat_t"] >= 48)
        if cooled and valid_atr:
            if long_sig:
                new_dir = 1
            elif short_sig:
                new_dir = -1
    else:
        if valid_atr:
            if d == 1 and short_sig:
                new_dir = -1
            elif d == -1 and long_sig:
                new_dir = 1

    if new_dir != 0:
        state["dir"] = new_dir
        state["atr_e"] = float(atr)
        state["units"] = 1
        state["last_add"] = float(close)
        state["ext"] = float(high) if new_dir == 1 else float(low)
        ae = state["atr_e"]
        if new_dir == 1:
            stop = state["ext"] - 4.0 * ae
        else:
            stop = state["ext"] + 4.0 * ae
        return {"target": 0.5 * new_dir, "stop": stop, "take": None}

    if d == 0:
        return {"target": 0.0, "stop": None, "take": None}

    # manage live trade
    ae = state["atr_e"]
    if d == 1:
        state["ext"] = max(state["ext"], float(high))
        stop = state["ext"] - 4.0 * ae
    else:
        state["ext"] = min(state["ext"], float(low))
        stop = state["ext"] + 4.0 * ae

    units = state.get("units", 1)
    target = 0.5 * units * d
    if units == 1 and d * (close - state["last_add"]) >= ae:
        state["units"] = 2
        state["last_add"] = float(close)
        target = 1.0 * d

    return {"target": target, "stop": stop, "take": None}

import math
import numpy as np

LOOKBACK = 48
HALF = 0.5
MAX_ENTRIES_PER_DAY = 2
DAY_MS = 86400000


def reset_trade(state):
    state["dir"] = 0
    state["eatr"] = 0.0
    state["anchor"] = 0.0
    state["last_add"] = 0.0
    state["added"] = False


def box_levels(state):
    d = state["dir"]
    a = state["anchor"]
    e = state["eatr"]
    if d > 0:
        return a - e, a + 2.0 * e
    return a + e, a - 2.0 * e


def strategy(hist, state, pos, ind):
    if "dir" not in state:
        reset_trade(state)
        state["day"] = -1
        state["day_count"] = 0

    close = hist.close[-1]

    # Daily entry counter (UTC day)
    day = int(hist.time[-1] // DAY_MS)
    if day != state["day"]:
        state["day"] = day
        state["day_count"] = 0

    # Trade closed by stop/take fill
    if state["dir"] != 0 and pos == 0.0:
        reset_trade(state)

    hh = ind.highest(hist.high, LOOKBACK)
    ll = ind.lowest(hist.low, LOOKBACK)
    atr_arr = ind.atr(hist, 14)
    if len(hh) < LOOKBACK + 1:
        return {"target": pos, "stop": None, "take": None}
    prior_high = hh[-2]
    prior_low = ll[-2]
    atr = atr_arr[-1]

    long_sig = (not math.isnan(prior_high)) and close > prior_high
    short_sig = (not math.isnan(prior_low)) and close < prior_low

    d = state["dir"]

    # In a trade
    if d != 0:
        # Opposite signal closes out
        if (d > 0 and short_sig) or (d < 0 and long_sig):
            reset_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        e = state["eatr"]
        # Ratchet the box
        if d > 0:
            while close >= state["anchor"] + 2.0 * e:
                state["anchor"] = state["anchor"] + 2.0 * e
        else:
            while close <= state["anchor"] - 2.0 * e:
                state["anchor"] = state["anchor"] - 2.0 * e

        target = pos
        # Pyramid once
        if not state["added"]:
            if (d > 0 and close >= state["last_add"] + e) or \
               (d < 0 and close <= state["last_add"] - e):
                state["added"] = True
                state["last_add"] = close
                target = float(d) * 2.0 * HALF

        stop, take = box_levels(state)
        return {"target": target, "stop": stop, "take": take}

    # Flat: look for entry
    if math.isnan(atr) or atr <= 0:
        return {"target": 0.0, "stop": None, "take": None}
    if state["day_count"] >= MAX_ENTRIES_PER_DAY:
        return {"target": 0.0, "stop": None, "take": None}

    nd = 0
    if long_sig:
        nd = 1
    elif short_sig:
        nd = -1
    if nd == 0:
        return {"target": 0.0, "stop": None, "take": None}

    state["dir"] = nd
    state["eatr"] = float(atr)
    state["anchor"] = float(close)
    state["last_add"] = float(close)
    state["added"] = False
    state["day_count"] = state["day_count"] + 1
    stop, take = box_levels(state)
    return {"target": float(nd) * HALF, "stop": stop, "take": take}

