                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        new_stop = hh - 4.0 * entry_atr
        stop = max(state.get("stop", new_stop), new_stop)
        state["stop"] = stop
        return {"target": 1.0, "stop": stop, "take": None}

    # Flat: look for entry
    if pos == 0.0 and golden:
        a = atr[-1]
        if not math.isnan(a) and a > 0:
            state["in_trade"] = True
            state["entry_price"] = float(c)
            state["entry_atr"] = float(a)
            state["hh"] = float(h)
            stop = float(h) - 4.0 * float(a)
            state["stop"] = stop
            return {"target": 1.0, "stop": stop, "take": None}

    return {"target": pos if pos != 0.0 else 0.0, "stop": None, "take": None}

