QUARTER = 0.25
MAX_ADDS = 1


def clear_trade(state):
    for k in ("in_trade", "dir", "entry", "atr", "steps", "be", "adds", "last_add"):
        if k in state:
            del state[k]


def trade_levels(state):
    d = state["dir"]
    e = state["entry"]
    a = state["atr"]
    shift = state["steps"] * 2.0 * a
    if d > 0:
        stop = e - 2.0 * a + shift
        take = e + 3.0 * a + shift
        if state["be"]:
            stop = max(stop, e)
    else:
        stop = e + 2.0 * a - shift
        take = e - 3.0 * a - shift
        if state["be"]:
            stop = min(stop, e)
    return stop, take


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]

    # Signals
    long_sig = False
    short_sig = False
    if t >= 49:
        hh = ind.highest(hist.high, 48)[-2]
        ll = ind.lowest(hist.low, 48)[-2]
        htf = hist.htf(240)
        if len(htf) >= 20:
            hc = htf.close
            ema = ind.ema(hc, 20)[-1]
            hlast = hc[-1]
            if not (math.isnan(hh) or math.isnan(ema)):
                long_sig = close > hh and hlast > ema
                short_sig = close < ll and hlast < ema

    atr_arr = ind.atr(hist, 14)
    atr_now = atr_arr[-1]

    # Detect a trade closed by stop/take
    if state.get("in_trade", False) and pos == 0.0:
        clear_trade(state)

    if state.get("in_trade", False):
        d = state["dir"]
        e = state["entry"]
        a = state["atr"]
        prog = (close - e) * d
        # Box shifting
        if a > 0:
            steps = int(math.floor(prog / (2.0 * a)))
            if steps > state["steps"]:
                state["steps"] = steps
            # Breakeven
            if prog >= 1.5 * a:
                state["be"] = True
        stop, take = trade_levels(state)

        # Opposite signal -> flat
        if (d > 0 and short_sig) or (d < 0 and long_sig):
            return {"target": 0.0, "stop": stop, "take": take}

        target = pos
        # Pyramid add
        if state["adds"] < MAX_ADDS and a > 0:
            if (close - state["last_add"]) * d >= a:
                target = d * (abs(pos) + QUARTER)
                target = max(-1.0, min(1.0, target))
                state["adds"] = state["adds"] + 1
                state["last_add"] = close
        return {"target": target, "stop": stop, "take": take}

    # Flat: look for entry
    if pos == 0.0 and not math.isnan(atr_now) and atr_now > 0:
        d = 0
        if long_sig:
            d = 1
        elif short_sig:
            d = -1
        if d != 0:
            state["in_trade"] = True
            state["dir"] = d
            state["entry"] = float(close)
            state["atr"] = float(atr_now)
            state["steps"] = 0
            state["be"] = False
            state["adds"] = 0
            state["last_add"] = float(close)
            stop, take = trade_levels(state)
            return {"target": d * QUARTER, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

import math
import numpy as np

N_LOOK = 96
ARM_BARS = 8
SIZE = 0.75
ATR_MULT = 2.0


def round_grid(x):
    return round(x / 0.05) * 0.05


def clear_trade(state):
    for k in ("in_trade", "entry", "eatr", "stop", "take", "anchor", "scaled", "entry_bar"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    low = hist.low[-1]
    high = hist.high[-1]

    prior_high = ind.highest(hist.high, N_LOOK)[-2]
    prior_low = ind.lowest(hist.low, N_LOOK)[-2]
    atr = ind.atr(hist, 14)[-1]

    # --- signals using arming from previous bars ---
    bull_signal = False
    if state.get("bull_armed", False):
        if t <= state.get("bull_exp", -1):
            if low <= state["bull_lvl"]:
                bull_signal = True
        else:
            state["bull_armed"] = False

    bear_signal = False
    if state.get("bear_armed", False):
        if t <= state.get("bear_exp", -1):
            if high >= state["bear_lvl"]:
                bear_signal = True
        else:
            state["bear_armed"] = False

    # --- update arming (level conditions, re-armed every breakout bar) ---
    if not math.isnan(prior_high) and close > prior_high:
        state["bull_armed"] = True
        state["bull_lvl"] = float(prior_high)
        state["bull_exp"] = t + ARM_BARS
    if not math.isnan(prior_low) and close < prior_low:
        state["bear_armed"] = True
        state["bear_lvl"] = float(prior_low)
        state["bear_exp"] = t + ARM_BARS

    # --- detect trade closed by stop/take ---
    if state.get("in_trade", False) and t > state.get("entry_bar", t) and pos <= 0.0:
        clear_trade(state)

    # --- manage open trade ---
    if state.get("in_trade", False):
        if bear_signal:
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        eatr = state["eatr"]
        entry = state["entry"]
        target = pos if t > state["entry_bar"] else SIZE

        if not state.get("scaled", False) and close >= entry + ATR_MULT * eatr:
            state["scaled"] = True
            cur = pos if pos > 0 else SIZE
            target = round_grid(cur / 2.0)

        while close >= state["anchor"] + ATR_MULT * eatr:
            state["anchor"] = state["anchor"] + ATR_MULT * eatr
            state["stop"] = state["stop"] + ATR_MULT * eatr
            state["take"] = state["take"] + ATR_MULT * eatr

        return {"target": target, "stop": state["stop"], "take": state["take"]}

    # --- entry when flat ---
    if pos == 0.0 and bull_signal and not math.isnan(atr) and atr > 0:
        state["in_trade"] = True
        state["entry"] = float(close)
        state["eatr"] = float(atr)
        state["anchor"] = float(close)
        state["stop"] = float(close - ATR_MULT * atr)
        state["take"] = float(close + ATR_MULT * atr)
        state["scaled"] = False
        state["entry_bar"] = t
        state["bull_armed"] = False
        return {"target": SIZE, "stop": state["stop"], "take": state["take"]}

    return {"target": pos if pos > 0 else 0.0, "stop": None, "take": None}

