import math
import numpy as np

BOX_N = 16
MAX_BOX_ATR = 6.0
UNIT = 0.25
MAX_ADDS = 1
ADD_ATR = 2.0
BE_ATR = 1.5
MAX_BARS = 256
COOLDOWN = 16


def box_signal(hist, ind, atr_now):
    """Return +1 long breakout, -1 short breakout, 0 none (prior 16 bars box)."""
    if len(hist) < BOX_N + 1:
        return 0
    hh = ind.highest(hist.high, BOX_N)
    ll = ind.lowest(hist.low, BOX_N)
    top = hh[-2]
    bot = ll[-2]
    if not (math.isfinite(top) and math.isfinite(bot) and math.isfinite(atr_now)):
        return 0
    if atr_now <= 0:
        return 0
    if top - bot > MAX_BOX_ATR * atr_now:
        return 0
    c = hist.close[-1]
    if c > top:
        return 1
    if c < bot:
        return -1
    return 0


def clear_trade(state, end_bar):
    state["in_trade"] = False
    state["last_end"] = end_bar
    for k in ("dir", "entry", "eatr", "sbar", "last_add", "adds", "be", "size"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    atr_arr = ind.atr(hist, 14)
    atr_now = atr_arr[-1]
    sig = box_signal(hist, ind, atr_now)

    if state.get("in_trade", False):
        sbar = state["sbar"]
        # position got flat (stop filled) after the entry was executed
        if t > sbar and abs(pos) < 1e-9:
            clear_trade(state, t)
        else:
            d = state["dir"]
            entry = state["entry"]
            eatr = state["eatr"]
            # opposite signal or time exit
            if (sig != 0 and sig == -d) or (t - sbar >= MAX_BARS):
                clear_trade(state, t + 1)
                return {"target": 0.0, "stop": None, "take": None}
            # breakeven activation
            if not state["be"] and d * (close - entry) >= BE_ATR * eatr:
                state["be"] = True
            size = state["size"]
            # pyramid
            if state["adds"] < MAX_ADDS and d * (close - state["last_add"]) >= ADD_ATR * eatr:
                size = min(1.0, size + UNIT)
                state["size"] = size
                state["adds"] = state["adds"] + 1
                state["last_add"] = close
            stop = entry if state["be"] else None
            return {"target": d * size, "stop": stop, "take": None}

    # flat: entry logic
    if abs(pos) > 1e-9:
        return {"target": 0.0, "stop": None, "take": None}
    last_end = state.get("last_end", -10 ** 9)
    if t - last_end < COOLDOWN:
        return {"target": 0.0, "stop": None, "take": None}
    if sig != 0:
        state["in_trade"] = True
        state["dir"] = sig
        state["entry"] = close
        state["eatr"] = float(atr_now)
        state["sbar"] = t
        state["last_add"] = close
        state["adds"] = 0
        state["be"] = False
        state["size"] = UNIT
        return {"target": sig * UNIT, "stop": None, "take": None}
    return {"target": 0.0, "stop": None, "take": None}

