    if d != 0 and abs(pos) < 1e-9 and t > state.get("sig_t", -1):
        state["dir"] = 0
        state["cd_t"] = t
        d = 0

    # ---- Donchian breakout arming (prior 48 bars) ----
    if t >= DON_N:
        dh = ind.highest(hist.high, DON_N)[-2]
        dl = ind.lowest(hist.low, DON_N)[-2]
        if not (math.isnan(dh) or math.isnan(dl)):
            if close > dh:
                state["al_t"] = t
                state["al_lvl"] = float(dh)
            if close < dl:
                state["as_t"] = t
                state["as_lvl"] = float(dl)

    # ---- 4h trend filter ----
    trend = 0
    h4 = hist.htf(HTF_MIN)
    if len(h4) >= HTF_EMA:
        e = ind.ema(h4.close, HTF_EMA)[-1]
        c4 = h4.close[-1]
        if c4 > e:
            trend = 1
        elif c4 < e:
            trend = -1

    # ---- entry signals (armed retest) ----
    long_sig = False
    short_sig = False
    if "al_t" in state:
        at = state["al_t"]
        if at < t <= at + ARM_BARS and low <= state["al_lvl"] and trend == 1:
            long_sig = True
    if "as_t" in state:
        at = state["as_t"]
        if at < t <= at + ARM_BARS and high >= state["as_lvl"] and trend == -1:
            short_sig = True

