    if d != 0:
        ea = state["eatr"]
        if d == 1:
            ext = max(state["ext"], high)
            state["ext"] = ext
            stop = ext - TRAIL_ATR * ea
            if short_sig:
                return {"target": 0.0, "stop": stop, "take": None}
            target = pos
            if state["adds"] < MAX_ADDS and close >= state["last_px"] + ADD_ATR * ea and pos > 0:
                target = min(1.0, pos + ADD_SIZE)
                state["adds"] = state["adds"] + 1
                state["last_px"] = float(close)
            return {"target": target, "stop": stop, "take": None}
        else:
            ext = min(state["ext"], low)
            state["ext"] = ext
            stop = ext + TRAIL_ATR * ea
            if long_sig:
