                state["adds"] = state["adds"] + 1
                state["last_px"] = float(close)
            return {"target": target, "stop": stop, "take": None}

    # ---- flat: entries ----
    if abs(pos) > 1e-9:
        return {"target": 0.0, "stop": None, "take": None}
    if "cd_t" in state and t < state["cd_t"] + COOLDOWN:
        return {"target": 0.0, "stop": None, "take": None}
    if math.isnan(atr_now) or atr_now <= 0:
        return {"target": 0.0, "stop": None, "take": None}

