        state["sig_t"] = t
        state["eatr"] = float(atr_now)
        state["ext"] = float(high)
        state["adds"] = 0
        state["last_px"] = float(close)
        if "al_t" in state:
            del state["al_t"]
        stop = high - TRAIL_ATR * atr_now
        return {"target": BASE_SIZE, "stop": stop, "take": None}
    if short_sig and not long_sig:
        state["dir"] = -1
        state["sig_t"] = t
