import numpy as np


def strategy(hist, state, pos, ind):
    close = hist.close
    n = len(close)
    if n < 3:
        return {"target": 0.0, "stop": None, "take": None}

    ema5 = ind.ema(close, 5)
    ema200 = ind.ema(close, 200)
    atr = ind.atr(hist, 14)

    e5_now, e5_prev = ema5[-1], ema5[-2]
    e200_now, e200_prev = ema200[-1], ema200[-2]

    bull_cross = (e5_prev <= e200_prev) and (e5_now > e200_now)
    bear_cross = (e5_prev >= e200_prev) and (e5_now < e200_now)

    # ---------------- In a trade ----------------
    if pos > 0 and state.get("in_trade", False):
        entry = state["entry"]
        eatr = state["entry_atr"]
        hh = state.get("hh", -math.inf)
        h = float(hist.high[-1])
        if h > hh:
            hh = h
        state["hh"] = hh

        if bear_cross:
            for k in ("in_trade", "entry", "entry_atr", "hh"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        hard_stop = entry - 2.0 * eatr
        trail_stop = hh - 2.0 * eatr
        stop = max(hard_stop, trail_stop)
        take = entry + 2.0 * eatr
        return {"target": pos, "stop": stop, "take": take}

    if pos > 0:
        # Position without state (should not happen); hold, exit on bearish cross
        if bear_cross:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # ---------------- Flat ----------------
    for k in ("in_trade", "entry", "entry_atr", "hh"):
        if k in state:
            del state[k]

    if not bull_cross:
        return {"target": 0.0, "stop": None, "take": None}

    h1 = hist.htf(60)
    h1c = h1.close
    if len(h1c) < 1:
        return {"target": 0.0, "stop": None, "take": None}
    h1ema = ind.ema(h1c, 20)
    if not (h1c[-1] > h1ema[-1]):
        return {"target": 0.0, "stop": None, "take": None}

    a = float(atr[-1])
    if not (a > 0) or math.isnan(a):
        return {"target": 0.0, "stop": None, "take": None}

    entry = float(close[-1])
    state["in_trade"] = True
    state["entry"] = entry
    state["entry_atr"] = a
    state["hh"] = -math.inf

    return {"target": 1.0, "stop": entry - 2.0 * a, "take": entry + 2.0 * a}

