def reset_trade(state):
    for k in ("active", "entry", "eatr", "last_add", "adds", "be"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    n = len(hist)
    close = hist.close[-1]

    # Detect a stop/take fill (or otherwise flat while we think we're in a trade)
    if state.get("active", False) and pos <= 0.0:
        reset_trade(state)

    if n < 50:
        return {"target": 0.0, "stop": None, "take": None}

    atr = ind.atr(hist, 14)[-1]
    prior_high = ind.highest(hist.high, 48)[-2]
    prior_low = ind.lowest(hist.low, 48)[-2]

    h1 = hist.htf(60)
    up_filter = False
    dn_filter = False
    if len(h1) >= 20:
        ema1 = ind.ema(h1.close, 20)
        c1 = h1.close[-1]
        e1 = ema1[-1]
        if not (math.isnan(e1)):
            up_filter = c1 > e1
            dn_filter = c1 < e1

    long_signal = (not math.isnan(prior_high)) and close > prior_high and up_filter
    short_signal = (not math.isnan(prior_low)) and close < prior_low and dn_filter

    if state.get("active", False):
        # Opposite signal -> flat
        if short_signal:
            reset_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        entry = state["entry"]
        eatr = state["eatr"]

        if close >= entry + eatr:
            state["be"] = True

        target = pos
        adds = state.get("adds", 0)
        if adds < 2 and close >= state["last_add"] + eatr and pos < 1.0:
            target = min(1.0, pos + 0.25)
            state["adds"] = adds + 1
            state["last_add"] = close

        stop = entry - 2.0 * eatr
        if state.get("be", False):
            stop = max(stop, entry)
        take = entry + 6.0 * eatr
        return {"target": target, "stop": stop, "take": take}

    # Flat: look for entry
    if long_signal and not math.isnan(atr) and atr > 0:
        state["active"] = True
        state["entry"] = float(close)
        state["eatr"] = float(atr)
        state["last_add"] = float(close)
        state["adds"] = 0
        state["be"] = False
        return {"target": 0.5,
                "stop": close - 2.0 * atr,
                "take": close + 6.0 * atr}

    return {"target": 0.0, "stop": None, "take": None}

