    hh = ind.highest(hist.high, 96)
    ll = ind.lowest(hist.low, 96)
    prior_high = hh[-2]
    prior_low = ll[-2]

    if math.isnan(prior_high) or math.isnan(prior_low):
        return {"target": pos, "stop": None, "take": None}

    long_sig = close > prior_high
    short_sig = close < prior_low

    in_trade = state.get("in_trade", False)
    entry_t = state.get("entry_t", -1)

    # Detect that a trade has closed: we were in a trade, the entry has filled
    # (t > entry_t), and we are now flat. Record the first flat bar.
    if in_trade and pos == 0.0 and t > entry_t:
        state["in_trade"] = False
        state["flat_t"] = t
        in_trade = False

    if in_trade:
        direction = state.get("dir", 0)
        # Time stop: once 16 bars have elapsed since the signal bar
        if t - entry_t >= 16:
            return {"target": 0.0, "stop": None, "take": None}
        # Opposite signal closes the trade (no reversal)
        if direction > 0 and short_sig:
            return {"target": 0.0, "stop": None, "take": None}
        if direction < 0 and long_sig:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": float(direction), "stop": None, "take": None}

    # Flat: check entry filters
    if pos != 0.0:
        # Safety: unexpected position; hold flat target
        return {"target": 0.0, "stop": None, "take": None}

    flat_t = state.get("flat_t", -1000000)
    if t - flat_t < 4:
        return {"target": 0.0, "stop": None, "take": None}

    day = int(hist.time[-1] // 86400000)
    if state.get("last_entry_day", -1) == day:
        return {"target": 0.0, "stop": None, "take": None}

    direction = 0
    if long_sig:
        direction = 1
    elif short_sig:
        direction = -1

    if direction != 0:
        state["in_trade"] = True
        state["entry_t"] = t
        state["dir"] = direction
        state["last_entry_day"] = day
        return {"target": float(direction), "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

