    if tdir != 0 and pos == 0.0 and state.get("live", False):
        state["dir"] = 0
        tdir = 0
    if tdir != 0 and pos != 0.0:
        state["live"] = True

    # --- update trailing extreme for open trade (bars after signal bar)
    if tdir == 1:
        state["ext"] = max(state["ext"], hi)
    elif tdir == -1:
        state["ext"] = min(state["ext"], lo)

    long_sig = False
    short_sig = False

    # --- long setup
    if not math.isnan(prior_hh) and hi > prior_hh:
        state["L_lvl"] = prior_hh
        state["L_t"] = t
        state["L_arm"] = True
    elif state.get("L_arm", False):
        if t - state["L_t"] <= 32:
            if lo <= state["L_lvl"]:
                long_sig = True
                state["L_arm"] = False
        else:
            state["L_arm"] = False

    # --- short setup
    if not math.isnan(prior_ll) and lo < prior_ll:
        state["S_lvl"] = prior_ll
        state["S_t"] = t
        state["S_arm"] = True
    elif state.get("S_arm", False):
        if t - state["S_t"] <= 32:
            if hi >= state["S_lvl"]:
                short_sig = True
                state["S_arm"] = False
        else:
            state["S_arm"] = False

    if long_sig and short_sig:
        short_sig = False

    target = pos
    new_dir = 0
    if long_sig and tdir != 1:
        new_dir = 1
    elif short_sig and tdir != -1:
        new_dir = -1

    if new_dir != 0 and not math.isnan(atr) and atr > 0:
        f = size_for(c, atr)
