    day = int(hist.time[-1] // 86400000)
    if state.get("day", -1) != day:
        state["day"] = day
        state["cnt"] = 0

    d = int(state.get("dir", 0))
    # detect trade closed by take-profit
    if d != 0 and pos == 0 and t > state.get("et", t):
        d = 0
        state["dir"] = 0

    # expire armed setups
    if state.get("la", False) and t - state.get("lt", t) > ARM_BARS:
        state["la"] = False
    if state.get("sa", False) and t - state.get("st", t) > ARM_BARS:
        state["sa"] = False

    # retest signals (on bars after arming)
    ls = False
    if state.get("la", False) and t > state.get("lt", t) and l <= state.get("ll", -1e18):
        ls = True
    ss = False
    if state.get("sa", False) and t > state.get("st", t) and h >= state.get("sl", 1e18):
        ss = True

    # arm new breakouts (level conditions, replace older levels)
    if not math.isnan(hh) and c > hh:
        state["la"] = True
        state["ll"] = hh
        state["lt"] = t
    if not math.isnan(ll) and c < ll:
        state["sa"] = True
        state["sl"] = ll
        state["st"] = t

    sig = 0
    if ls and not ss:
        sig = 1
    elif ss and not ls:
        sig = -1

    can_enter = state.get("cnt", 0) < 1 and not math.isnan(atr) and atr > 0

    enter = False
    if d == 0:
        if sig != 0 and can_enter:
            enter = True
    elif sig == -d:
        if can_enter:
            enter = True
        else:
            state["dir"] = 0
            return {"target": 0.0, "stop": None, "take": None}

