def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])

    e5 = ind.ema(close, 5)
    e100 = ind.ema(close, 100)
    atr = ind.atr(hist, 14)

    cross_up = False
    cross_dn = False
    if len(close) >= 2:
        p5, p100 = e5[-2], e100[-2]
        n5, n100 = e5[-1], e100[-1]
        if not (math.isnan(p5) or math.isnan(p100) or math.isnan(n5) or math.isnan(n100)):
            cross_up = (p5 <= p100) and (n5 > n100)
            cross_dn = (p5 >= p100) and (n5 < n100)

    in_trade = state.get("in_trade", False)

    # Detect trade end (TP fill or executed exit)
    if in_trade and t > state.get("entry_t", t) and pos == 0.0:
        in_trade = False
        state["in_trade"] = False
        state["flat_t"] = t

    if in_trade:
        d = state["dir"]
        entry = state["entry"]
        eatr = state["eatr"]
        take = entry + d * 2.0 * eatr
        # opposite signal -> exit
        if (d > 0 and cross_dn) or (d < 0 and cross_up):
            return {"target": 0.0, "stop": None, "take": None}
        # time exit
        if t - state["entry_t"] >= 32:
            return {"target": 0.0, "stop": None, "take": None}
        tgt = pos if pos != 0.0 else state["size"] * d
        return {"target": tgt, "stop": None, "take": take}

    # Flat: check cooldown
    flat_t = state.get("flat_t", -1000000)
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}
    if t - flat_t < 4:
        return {"target": 0.0, "stop": None, "take": None}

    a = float(atr[-1])
    if math.isnan(a) or a <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    d = 0
    if cross_up:
        d = 1
    elif cross_dn:
        d = -1
    if d == 0:
        return {"target": 0.0, "stop": None, "take": None}

    size = 0.005 * c / (1.0 * a)
    size = min(1.0, max(0.05, size))

    state["in_trade"] = True
    state["dir"] = d
    state["entry"] = c
    state["eatr"] = a
    state["entry_t"] = t
    state["size"] = size

    take = c + d * 2.0 * a
    return {"target": d * size, "stop": None, "take": take}

