def strategy(hist, state, pos, ind) -> dict:
    close = hist.close
    rsi = ind.rsi(close, RSI_LEN)
    r_now = rsi[-1]
    r_prev = rsi[-2]

    # Track entries per UTC calendar day (day of the signal bar)
    day = int(hist.time[-1] // DAY_MS)
    if state.get("day", -1) != day:
        state["day"] = day
        state["count"] = 0

    if r_now is None or r_prev is None or math.isnan(r_now) or math.isnan(r_prev):
        return {"target": pos, "stop": None, "take": None}

    long_sig = (r_prev <= LOWER) and (r_now > LOWER)
    short_sig = (r_prev >= UPPER) and (r_now < UPPER)

    # In a trade: opposite signal -> go flat
    if pos > 0:
        if short_sig:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}
    if pos < 0:
        if long_sig:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # Flat: look for entries, respecting daily cap
    count = int(state.get("count", 0))
    if count < MAX_ENTRIES_PER_DAY:
        if long_sig:
            state["count"] = count + 1
            return {"target": SIZE, "stop": None, "take": None}
        if short_sig:
