def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]

    if len(hist) < 50:
        return {"target": pos, "stop": None, "take": None}

    hh = ind.highest(hist.high, 48)[-2]
    ll = ind.lowest(hist.low, 48)[-2]
    atr = ind.atr(hist, 14)[-1]

    # 4h trend filter on the latest completed 4h candle
    h4 = hist.htf(240)
    up_ok = False
    dn_ok = False
    if len(h4) >= 20:
        h4c = h4.close
        e20 = ind.ema(h4c, 20)
        up_ok = h4c[-1] > e20[-1]
        dn_ok = h4c[-1] < e20[-1]

    # Retest signals using setups armed on earlier bars
    long_sig = False
    short_sig = False
    if "l_arm_t" in state:
        at = state["l_arm_t"]
        if t > at + 8:
            del state["l_arm_t"]
            del state["l_lvl"]
        elif t > at and low <= state["l_lvl"] and up_ok:
            long_sig = True
    if "s_arm_t" in state:
        at = state["s_arm_t"]
        if t > at + 8:
            del state["s_arm_t"]
            del state["s_lvl"]
        elif t > at and high >= state["s_lvl"] and dn_ok:
            short_sig = True

    # Arm or re-arm setups (level condition, checked every bar)
    if not math.isnan(hh) and close > hh:
        state["l_arm_t"] = t
        state["l_lvl"] = float(hh)
    if not math.isnan(ll) and close < ll:
        state["s_arm_t"] = t
        state["s_lvl"] = float(ll)

    d = state.get("dir", 0)

    # Detect a trade closed by a stop fill
    if d != 0 and pos == 0.0 and t > state.get("entry_t", t):
        for k in ("dir", "entry", "eatr", "entry_t", "be"):
            if k in state:
                del state[k]
        d = 0

    if d != 0:
        entry = state["entry"]
        eatr = state["eatr"]
        # Opposite signal closes the trade
        if (d == 1 and short_sig) or (d == -1 and long_sig):
            for k in ("dir", "entry", "eatr", "entry_t", "be"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}
        target = pos if pos != 0.0 else float(d)
        if not state.get("be", False):
            profit = (close - entry) * d
            if profit >= 2.0 * eatr:
                state["be"] = True
                target = 0.5 * d
        stop = entry if state.get("be", False) else None
        return {"target": target, "stop": stop, "take": None}

    # Flat: look for entries
    if long_sig and not short_sig:
        state["dir"] = 1
        state["entry"] = float(close)
        state["eatr"] = float(atr)
        state["entry_t"] = t
        state["be"] = False
        if "l_arm_t" in state:
            del state["l_arm_t"]
            del state["l_lvl"]
        return {"target": 1.0, "stop": None, "take": None}
    if short_sig and not long_sig:
        state["dir"] = -1
        state["entry"] = float(close)
        state["eatr"] = float(atr)
        state["entry_t"] = t
        state["be"] = False
        if "s_arm_t" in state:
            del state["s_arm_t"]
            del state["s_lvl"]
        return {"target": -1.0, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

import math
import numpy as np


def reset_trade(state):
    for k in ("dir", "entry", "atr", "last_add", "adds", "size", "steps"):
        if k in state:
            del state[k]


def box(state):
    d = state["dir"]
    e = state["entry"]
    a = state["atr"]
    shift = state["steps"] * 2.0 * a
    stop = e - d * 2.0 * a + d * shift
    take = e + d * 3.0 * a + d * shift
    return stop, take


def strategy(hist, state, pos, ind):
    close = hist.close
    c = float(close[-1])
    rsi = ind.rsi(close, 21)
    r_now = float(rsi[-1])
    r_prev = float(rsi[-2]) if len(rsi) >= 2 else float("nan")
    atr_arr = ind.atr(hist, 14)
    atr_now = float(atr_arr[-1])

    long_sig = False
    short_sig = False
    if not (math.isnan(r_now) or math.isnan(r_prev)):
        long_sig = r_prev <= 25.0 and r_now > 25.0
        short_sig = r_prev >= 75.0 and r_now < 75.0

    # trade ended (stop/take/exit) -> reset
    if "dir" in state and abs(pos) < 1e-9:
        reset_trade(state)

    if "dir" not in state:
        if abs(pos) > 1e-9:
            return {"target": 0.0, "stop": None, "take": None}
        if math.isnan(atr_now) or atr_now <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        d = 0
        if long_sig:
            d = 1
        elif short_sig:
            d = -1
        if d == 0:
            return {"target": 0.0, "stop": None, "take": None}
        state["dir"] = d
        state["entry"] = c
        state["atr"] = atr_now
        state["last_add"] = c
        state["adds"] = 0
        state["size"] = 0.5
        state["steps"] = 0
        stop, take = box(state)
        return {"target": d * 0.5, "stop": stop, "take": take}

    # live trade
    d = state["dir"]
    a = state["atr"]
    e = state["entry"]

    # update ratchet
    profit = d * (c - e)
    k = int(math.floor(profit / (2.0 * a))) if a > 0 else 0
    if k > state["steps"]:
        state["steps"] = k

    stop, take = box(state)

    # opposite signal -> flat
    if (d == 1 and short_sig) or (d == -1 and long_sig):
        return {"target": 0.0, "stop": stop, "take": take}

    # pyramiding
    size = state["size"]
    if state["adds"] < 2 and size < 1.0 - 1e-9:
        if d * (c - state["last_add"]) >= 2.0 * a:
            size = min(1.0, size + 0.5)
            state["size"] = size
            state["adds"] = state["adds"] + 1
            state["last_add"] = c

    return {"target": d * state["size"], "stop": stop, "take": take}

