    r_now = float(rsi[-1])
    r_prev = float(rsi[-2]) if t >= 1 else float("nan")
    a_now = float(atr[-1])

    day = int(hist.time[-1] // 86400000)

    in_trade = state.get("in_trade", False)

    # Safety: if a trade was marked live but the position vanished after it was filled
    if in_trade and pos == 0.0 and t > state.get("entry_bar", t) + 1:
        state["in_trade"] = False
        state["flat_bar"] = t
        in_trade = False

    if in_trade:
        entry = state["entry_price"]
        eatr = state["entry_atr"]
        half = state.get("half", False)

        # Runner / trade exit: RSI crosses down through 75
        if t > state["entry_bar"] and not (math.isnan(r_now) or math.isnan(r_prev)):
            if r_prev >= 75.0 and r_now < 75.0:
                state["in_trade"] = False
                state["half"] = False
                state["flat_bar"] = t
                return {"target": 0.0, "stop": None, "take": None}

        # Partial profit: close at least 2 ATR in profit -> bank half
        if (not half) and (c - entry > 0.0) and (c - entry >= 2.0 * eatr):
            state["half"] = True
            half = True

        tgt = 0.5 if half else 1.0
        return {"target": tgt, "stop": None, "take": None}

    # Flat: look for entry
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    if "flat_bar" in state and t - state["flat_bar"] < 16:
        return {"target": 0.0, "stop": None, "take": None}

    if state.get("last_entry_day", -1) == day:
        return {"target": 0.0, "stop": None, "take": None}

