import math
import numpy as np

BOX_N = 32
BOX_MAX_ATR = 6.0
MAX_TRADES_PER_DAY = 3
RISK = 0.01
RISK_ATR_MULT = 2.0
SIZE_CAP = 1.0
SIZE_FLOOR = 0.05
HTF_MIN = 60
HTF_EMA = 50
DAY_MS = 86400000


def compute_signal(hist, ind):
    n = len(hist)
    if n < BOX_N + 2:
        return 0, float("nan")
    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])
    if not (atr > 0) or math.isnan(atr):
        return 0, atr
    box_hi = float(ind.highest(hist.high, BOX_N)[-2])
    box_lo = float(ind.lowest(hist.low, BOX_N)[-2])
    if math.isnan(box_hi) or math.isnan(box_lo):
        return 0, atr
    if (box_hi - box_lo) > BOX_MAX_ATR * atr:
        return 0, atr

    h1 = hist.htf(HTF_MIN)
    if len(h1) < HTF_EMA:
        return 0, atr
    h1_close = h1.close
    ema = ind.ema(h1_close, HTF_EMA)
    last_c = float(h1_close[-1])
    last_e = float(ema[-1])
    if math.isnan(last_e):
        return 0, atr

    close = float(hist.close[-1])
    if close > box_hi and last_c > last_e:
        return 1, atr
    if close < box_lo and last_c < last_e:
        return -1, atr
    return 0, atr


def strategy(hist, state, pos, ind):
    day = int(hist.time[-1]) // DAY_MS
    if state.get("day", -1) != day:
        state["day"] = day
        state["count"] = 0

    sig, atr = compute_signal(hist, ind)

    if pos != 0:
        if (pos > 0 and sig == -1) or (pos < 0 and sig == 1):
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # flat
    if sig != 0 and state.get("count", 0) < MAX_TRADES_PER_DAY:
        close = float(hist.close[-1])
        size = RISK * close / (RISK_ATR_MULT * atr)
        size = max(SIZE_FLOOR, min(SIZE_CAP, size))
        state["count"] = state.get("count", 0) + 1
        return {"target": float(sig) * size, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

