DAY_MS = 86400000


def clear_trade(state):
    for k in ("in_trade", "entry", "eatr", "scaled", "trail_k", "sig_t"):
        if k in state:
            del state[k]


def round_grid(x):
    return round(x / 0.05) * 0.05


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])
    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])

    # Box signals (prior 16 bars, excluding current)
    long_sig = False
    short_sig = False
    if t >= BOX_N and not math.isnan(atr) and atr > 0:
        hh = ind.highest(hist.high, BOX_N)
        ll = ind.lowest(hist.low, BOX_N)
        box_top = float(hh[-2])
        box_bot = float(ll[-2])
        if not (math.isnan(box_top) or math.isnan(box_bot)):
            if box_top - box_bot <= BOX_MAX_ATR * atr:
                if c > box_top:
                    long_sig = True
                if c < box_bot:
                    short_sig = True

    # Detect trade closed by stop/take
    if state.get("in_trade", False):
        if pos == 0.0 and t > state.get("sig_t", t):
            clear_trade(state)

    # Manage open trade
    if state.get("in_trade", False):
        entry = state["entry"]
        eatr = state["eatr"]

        if short_sig:
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        k = int(math.floor((c - entry) / (TRAIL_STEP_ATR * eatr)))
        if k > state.get("trail_k", 0):
            state["trail_k"] = k
        trail_k = state.get("trail_k", 0)

        hard_stop = entry - STOP_ATR * eatr
        trail_stop = entry - STOP_ATR * eatr + trail_k * TRAIL_STEP_ATR * eatr
        stop = max(hard_stop, trail_stop)
        take = entry + TP_ATR * eatr

        target = pos
        if (not state.get("scaled", False)) and pos > 0 and c >= entry + SCALE_ATR * eatr:
            half = round_grid(pos / 2.0)
            if half < 0.05:
                half = 0.05
            target = half
            state["scaled"] = True

        return {"target": target, "stop": stop, "take": take}

    # Flat: look for entry
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    if not long_sig:
        return {"target": 0.0, "stop": None, "take": None}

    h4 = hist.htf(240)
    if len(h4) < 20:
        return {"target": 0.0, "stop": None, "take": None}
    ema4 = ind.ema(h4.close, 20)
    h4c = float(h4.close[-1])
    h4e = float(ema4[-1])
    if math.isnan(h4e) or not (h4c > h4e):
        return {"target": 0.0, "stop": None, "take": None}

    day = int(hist.time[-1]) // DAY_MS
    if state.get("day", -1) != day:
        state["day"] = day
        state["day_entries"] = 0
    if state.get("day_entries", 0) >= MAX_ENTRIES_PER_DAY:
        return {"target": 0.0, "stop": None, "take": None}

    size = RISK * c / (RISK_ATR * atr)
    size = min(SIZE_CAP, max(SIZE_FLOOR, size))
    size = round_grid(size)
    if size < SIZE_FLOOR:
        size = SIZE_FLOOR
    if size > SIZE_CAP:
        size = SIZE_CAP

    state["day_entries"] = state.get("day_entries", 0) + 1
    state["in_trade"] = True
    state["entry"] = c
    state["eatr"] = atr
    state["scaled"] = False
    state["trail_k"] = 0
    state["sig_t"] = t

    stop = c - STOP_ATR * atr
    take = c + TP_ATR * atr
    return {"target": size, "stop": stop, "take": take}

