import math
import numpy as np

LOOKBACK = 96
ARM_BARS = 32
BE_ATR = 0.5
SCALE_ATR = 2.0


def clear_trade(state):
    for k in ("side", "entry", "eatr", "be", "scaled"):
        if k in state:
            del state[k]


def open_trade(state, side, price, atr):
    state["side"] = side
    state["entry"] = float(price)
    state["eatr"] = float(atr)
    state["be"] = False
    state["scaled"] = False


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    c = float(hist.close[-1])
    h = float(hist.high[-1])
    l = float(hist.low[-1])
    atr = float(ind.atr(hist, 14)[-1])

    if len(hist) < LOOKBACK + 2 or not np.isfinite(atr):
        return {"target": pos, "stop": None, "take": None}

    # prior 96-bar Donchian levels (bars before the current one)
    hh = float(ind.highest(hist.high, LOOKBACK)[-2])
    ll = float(ind.lowest(hist.low, LOOKBACK)[-2])

    # detect exit by stop fill
    if "side" in state and pos == 0.0:
        clear_trade(state)

    # expire arms
    if "lt" in state and t - state["lt"] > ARM_BARS:
        del state["lt"]
        del state["lv"]
    if "st" in state and t - state["st"] > ARM_BARS:
        del state["st"]
        del state["sv"]

    # retest signals (armed on previous bars)
    long_sig = ("lt" in state and 1 <= t - state["lt"] <= ARM_BARS
                and l <= state["lv"])
    short_sig = ("st" in state and 1 <= t - state["st"] <= ARM_BARS
                 and h >= state["sv"])

    # arm on breakouts (level condition, re-arms each bar beyond level)
    if c > hh:
        state["lt"] = t
        state["lv"] = hh
    if c < ll:
        state["st"] = t
        state["sv"] = ll

    side = int(state.get("side", 0))
    target = pos
    stop = None

    new_side = 0
    if side == 0:
        if long_sig and not short_sig:
            new_side = 1
        elif short_sig and not long_sig:
            new_side = -1
    elif side == 1 and short_sig:
        new_side = -1
    elif side == -1 and long_sig:
        new_side = 1

    if new_side != 0:
        open_trade(state, new_side, c, atr)
        if new_side == 1:
            if "lt" in state:
                del state["lt"]
                del state["lv"]
        else:
            if "st" in state:
                del state["st"]
                del state["sv"]
        return {"target": float(new_side), "stop": None, "take": None}

    if side != 0:
        entry = state["entry"]
        eatr = state["eatr"]
        profit = (c - entry) * side
        if profit >= BE_ATR * eatr:
            state["be"] = True
        if profit >= SCALE_ATR * eatr and not state["scaled"]:
            state["scaled"] = True
        target = side * (0.5 if state["scaled"] else 1.0)
        stop = entry if state["be"] else None
        return {"target": target, "stop": stop, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

