    if trade_dir != 0:
        entry = float(state["entry"])
        eatr = float(state["eatr"])
        be = bool(state.get("be", False))

        # Opposite signal -> exit immediately (no reversal)
        if (trade_dir > 0 and short_sig) or (trade_dir < 0 and long_sig):
            for k in ("dir", "entry", "eatr", "be"):
