import math
import numpy as np

BOX_N = 64
MAX_BOX_ATR = 6.0
TP_ATR = 3.0
BE_TRIGGER_ATR = 2.0


def clear_trade(state):
    for k in ("dir", "entry", "eatr", "be"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    close = hist.close[-1]
    atr = ind.atr(hist, 14)[-1]
    box_hi = ind.highest(hist.high, BOX_N)[-2]
    box_lo = ind.lowest(hist.low, BOX_N)[-2]

    signal = 0
    if not (math.isnan(atr) or math.isnan(box_hi) or math.isnan(box_lo)):
        if (box_hi - box_lo) <= MAX_BOX_ATR * atr:
            if close > box_hi:
                signal = 1
            elif close < box_lo:
                signal = -1

    # Flat: clear any stale trade state (stop/take fill), look for entry
    if pos == 0:
        clear_trade(state)
        if signal != 0:
            entry = close
            state["dir"] = signal
            state["entry"] = entry
            state["eatr"] = atr
            state["be"] = False
            take = entry + signal * TP_ATR * atr
            return {"target": float(signal), "stop": None, "take": take}
        return {"target": 0.0, "stop": None, "take": None}

    # In a position
    if "dir" not in state:
        # Unknown trade state; just hold without orders
        return {"target": pos, "stop": None, "take": None}

    d = int(state["dir"])
    entry = state["entry"]
    eatr = state["eatr"]

    # Opposite signal -> exit at next open
    if signal == -d:
        return {"target": 0.0, "stop": None, "take": None}

    # Breakeven ratchet
    if not state["be"] and d * (close - entry) >= BE_TRIGGER_ATR * eatr:
        state["be"] = True

    stop = entry if state["be"] else None
    take = entry + d * TP_ATR * eatr
    return {"target": pos, "stop": stop, "take": take}

