import math
import numpy as np

RSI_LEN = 14
ATR_LEN = 14
OS_LEVEL = 30.0
OB_LEVEL = 70.0
MAX_ENTRIES_PER_DAY = 2
RISK = 0.01
ATR_MULT = 1.0
SIZE_CAP = 1.0
SIZE_FLOOR = 0.05
DAY_MS = 86400000


def strategy(hist, state, pos, ind):
    close = hist.close
    n = len(hist)
    if n < 3:
        return {"target": pos, "stop": None, "take": None}

    rsi = ind.rsi(close, RSI_LEN)
    r_now = rsi[-1]
    r_prev = rsi[-2]

    # Track UTC calendar day entry count
    day = int(hist.time[-1] // DAY_MS)
    if state.get("day", -1) != day:
        state["day"] = day
        state["entries"] = 0

    long_sig = False
    short_sig = False
    if not (math.isnan(r_now) or math.isnan(r_prev)):
        # Cross up through 30: at-or-below previously, strictly above now
        long_sig = (r_prev <= OS_LEVEL) and (r_now > OS_LEVEL)
        # Cross down through 70: at-or-above previously, strictly below now
        short_sig = (r_prev >= OB_LEVEL) and (r_now < OB_LEVEL)

    # In a trade: bail on opposite signal, otherwise hold
    if pos > 0:
        if short_sig:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}
    if pos < 0:
        if long_sig:
            return {"target": 0.0, "stop": None, "take": None}
        return {"target": pos, "stop": None, "take": None}

    # Flat: look for entries
    if (long_sig or short_sig) and state.get("entries", 0) < MAX_ENTRIES_PER_DAY:
        atr = ind.atr(hist, ATR_LEN)[-1]
        c = close[-1]
        if not math.isnan(atr) and atr > 0:
            size = RISK * c / (ATR_MULT * atr)
            size = min(SIZE_CAP, max(SIZE_FLOOR, size))
            state["entries"] = state.get("entries", 0) + 1
            state["entry_price"] = float(c)
            state["entry_atr"] = float(atr)
            direction = 1.0 if long_sig else -1.0
            return {"target": direction * size, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

