def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])

    rsi = ind.rsi(close, 21)
    r_now = float(rsi[-1])
    r_prev = float(rsi[-2]) if len(rsi) >= 2 else float("nan")

    atr_arr = ind.atr(hist, 14)
    atr_now = float(atr_arr[-1])

    long_sig = False
    short_sig = False
    if not (math.isnan(r_now) or math.isnan(r_prev)):
        long_sig = (r_prev <= 25.0) and (r_now > 25.0)
        short_sig = (r_prev >= 75.0) and (r_now < 75.0)

    in_trade = state.get("in_trade", False)

    # The trade was closed by the take-profit (or is otherwise flat): reset the trade state.
    # The entry_bar check keeps the state alive on the signal bar itself, when pos is still 0.
    if in_trade and abs(pos) < 1e-9 and state.get("entry_bar", -1) != t:
        in_trade = False
        for k in ("in_trade", "dir", "entry", "eatr", "last_add", "adds", "size", "entry_bar"):
            if k in state:
                del state[k]

    if not in_trade:
        if abs(pos) > 1e-9:
            # Unexpected leftover position without trade state: flatten it.
            return {"target": 0.0, "stop": None, "take": None}
        if math.isnan(atr_now) or atr_now <= 0:
            return {"target": 0.0, "stop": None, "take": None}
        d = 0
        if long_sig:
            d = 1
        elif short_sig:
            d = -1
        if d == 0:
            return {"target": 0.0, "stop": None, "take": None}
        state["in_trade"] = True
        state["dir"] = d
        state["entry"] = c
        state["eatr"] = atr_now
        state["last_add"] = c
        state["adds"] = 0
        state["size"] = 0.5
        state["entry_bar"] = t
        take = c + d * 2.0 * atr_now
        return {"target": d * 0.5, "stop": None, "take": take}

    # Trade is live.
    d = int(state["dir"])
    entry = float(state["entry"])
    eatr = float(state["eatr"])
    take = entry + d * 2.0 * eatr

    # Opposite signal: exit at the next open.
    if (d == 1 and short_sig) or (d == -1 and long_sig):
        for k in ("in_trade", "dir", "entry", "eatr", "last_add", "adds", "size", "entry_bar"):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    size = float(state["size"])
    adds = int(state["adds"])
    last_add = float(state["last_add"])

    # Pyramid: add half size when price has moved at least 1 entry ATR in our favor
    # since the last add, at most 2 adds, total size capped at 1.0.
    if adds < 2 and size < 1.0 - 1e-9:
        if d * (c - last_add) >= eatr:
            size = min(1.0, size + 0.5)
            adds += 1
            state["size"] = size
            state["adds"] = adds
            state["last_add"] = c

    return {"target": d * size, "stop": None, "take": take}

import math
import numpy as np

LOOKBACK = 96
ARM_BARS = 8


def clear_trade(state):
    for k in ("side", "entry", "eatr", "entry_t", "be", "scaled"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    high = hist.high
    low = hist.low
    close = float(hist.close[-1])
    h = float(high[-1])
    l = float(low[-1])

    atr_arr = ind.atr(hist, 14)
    atr = float(atr_arr[-1])
    hh = ind.highest(high, LOOKBACK)
    ll = ind.lowest(low, LOOKBACK)
    prior_hh = float(hh[-2])
    prior_ll = float(ll[-2])

    # --- detect trade closed externally (stop fill) ---
    side = int(state.get("side", 0))
    if side != 0 and pos == 0.0 and t > int(state.get("entry_t", t)):
        clear_trade(state)
        side = 0

    # --- retest signals using currently armed levels ---
    long_sig = False
    short_sig = False
    if "long_t" in state:
        dt = t - int(state["long_t"])
        if dt > ARM_BARS:
            del state["long_t"]
            del state["long_lvl"]
        elif dt >= 1 and l <= float(state["long_lvl"]):
            long_sig = True
            del state["long_t"]
            del state["long_lvl"]
    if "short_t" in state:
        dt = t - int(state["short_t"])
        if dt > ARM_BARS:
            del state["short_t"]
            del state["short_lvl"]
        elif dt >= 1 and h >= float(state["short_lvl"]):
            short_sig = True
            del state["short_t"]
            del state["short_lvl"]

    # --- arm new setups on fresh breakouts ---
    if not math.isnan(prior_hh) and h > prior_hh:
        state["long_t"] = t
        state["long_lvl"] = prior_hh
    if not math.isnan(prior_ll) and l < prior_ll:
        state["short_t"] = t
        state["short_lvl"] = prior_ll

    # --- manage open trade ---
    if side != 0:
        if (side == 1 and short_sig) or (side == -1 and long_sig):
            clear_trade(state)
            return {"target": 0.0, "stop": None, "take": None}

        entry = float(state["entry"])
        eatr = float(state["eatr"])
        profit = (close - entry) * side
        if profit >= 1.0 * eatr:
            state["be"] = True
        target = pos if pos != 0.0 else float(side)
        if profit >= 3.0 * eatr and not state.get("scaled", False):
            state["scaled"] = True
            target = 0.5 * side

        hard = entry - side * 2.0 * eatr
        if state.get("be", False):
            if side == 1:
                stop = max(hard, entry)
            else:
                stop = min(hard, entry)
        else:
            stop = hard
        return {"target": target, "stop": stop, "take": None}

    # --- flat: entries ---
    if pos == 0.0 and not math.isnan(atr) and atr > 0:
        new_side = 0
        if long_sig and not short_sig:
            new_side = 1
        elif short_sig and not long_sig:
            new_side = -1
        if new_side != 0:
            state["side"] = new_side
            state["entry"] = close
            state["eatr"] = atr
            state["entry_t"] = t
            state["be"] = False
            state["scaled"] = False
            stop = close - new_side * 2.0 * atr
            return {"target": float(new_side), "stop": stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

