        adds = int(state["adds"])
        last_add = float(state["last_add"])
        if adds < 2:
            if (d == 1 and c >= last_add + a) or (d == -1 and c <= last_add - a):
                adds += 1
                state["adds"] = adds
                state["last_add"] = c

        size = min(1.0, 0.5 * (1 + adds))
        stop = anchor - d * 2.0 * a
        take = anchor + d * 2.0 * a
        return {"target": d * size, "stop": stop, "take": take}

    # Flat: look for entries
    if abs(pos) > 1e-9:
        # Unexpected residual position: flatten
        return {"target": 0.0, "stop": None, "take": None}

    if int(state.get("day_entries", 0)) >= 3:
        return {"target": 0.0, "stop": None, "take": None}

    atr = ind.atr(hist, 14)
    a = float(atr[-1])
    if math.isnan(a) or a <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    nd = 0
    if long_sig:
        nd = 1
    elif short_sig:
        nd = -1
    if nd == 0:
        return {"target": 0.0, "stop": None, "take": None}

    state["dir"] = nd
    state["entry_t"] = t
    state["entry_px"] = c
    state["atr"] = a
    state["adds"] = 0
    state["last_add"] = c
    state["anchor"] = c
    state["day_entries"] = int(state.get("day_entries", 0)) + 1

    stop = c - nd * 2.0 * a
    take = c + nd * 2.0 * a
    return {"target": nd * 0.5, "stop": stop, "take": take}

