import math
import numpy as np

RSI_LEN = 21
RSI_LOW = 30.0
RSI_HIGH = 70.0
HTF_MIN = 240
HTF_EMA = 50
ATR_LEN = 14
RISK = 0.01
RISK_ATR = 2.0
SIZE_MIN = 0.05
SIZE_MAX = 1.0
TP_ATR = 3.0
COOLDOWN = 48
DAY_MS = 86400000


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])

    rsi = ind.rsi(close, RSI_LEN)
    r_now = float(rsi[-1])
    r_prev = float(rsi[-2]) if len(rsi) >= 2 else float("nan")
    rsi_ok = not (math.isnan(r_now) or math.isnan(r_prev))
    cross_up = rsi_ok and r_prev <= RSI_LOW and r_now > RSI_LOW
    cross_dn = rsi_ok and r_prev >= RSI_HIGH and r_now < RSI_HIGH

    in_trade = state.get("in_trade", False)

    # Detect that a live trade has ended (TP fill or signal exit executed)
    if in_trade and pos == 0.0:
        state["in_trade"] = False
        state["last_flat"] = t
        in_trade = False

    if in_trade:
        side = state.get("side", 0)
        entry = state.get("entry", c)
        atr_e = state.get("atr_e", 0.0)
        if side > 0:
            take = entry + TP_ATR * atr_e
            if cross_dn:
                return {"target": 0.0, "stop": None, "take": take}
        else:
            take = entry - TP_ATR * atr_e
            if cross_up:
                return {"target": 0.0, "stop": None, "take": take}
        return {"target": pos, "stop": None, "take": take}

    # Flat: look for entries
    if pos != 0.0:
        # Unexpected position without tracked trade; hold it
        return {"target": pos, "stop": None, "take": None}

    last_flat = state.get("last_flat", -10 ** 9)
    if t - last_flat < COOLDOWN:
        return {"target": 0.0, "stop": None, "take": None}

    day = int(hist.time[-1]) // DAY_MS
    if state.get("last_day", -1) == day:
        return {"target": 0.0, "stop": None, "take": None}

    if not (cross_up or cross_dn):
        return {"target": 0.0, "stop": None, "take": None}

    htf = hist.htf(HTF_MIN)
    if len(htf) < 1:
        return {"target": 0.0, "stop": None, "take": None}
    hema = ind.ema(htf.close, HTF_EMA)
    hc = float(htf.close[-1])
    he = float(hema[-1])
    if math.isnan(he):
        return {"target": 0.0, "stop": None, "take": None}

    atr = float(ind.atr(hist, ATR_LEN)[-1])
    if math.isnan(atr) or atr <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    side = 0
    if cross_up and hc > he:
        side = 1
    elif cross_dn and hc < he:
        side = -1
    if side == 0:
        return {"target": 0.0, "stop": None, "take": None}

    size = RISK * c / (RISK_ATR * atr)
    size = max(SIZE_MIN, min(SIZE_MAX, size))

    state["in_trade"] = True
    state["side"] = side
    state["entry"] = c
    state["atr_e"] = atr
    state["last_day"] = day

    take = c + TP_ATR * atr if side > 0 else c - TP_ATR * atr
    return {"target": side * size, "stop": None, "take": take}

