    h1 = hist.htf(60)
    if len(h1) < 50:
        return {"target": 0.0, "stop": None, "take": None}
    h1c = h1.close
    ema50 = ind.ema(h1c, 50)
    if not (float(h1c[-1]) > float(ema50[-1])):
        return {"target": 0.0, "stop": None, "take": None}
    if not (a > 0) or math.isnan(a):
        return {"target": 0.0, "stop": None, "take": None}

    state["in_trade"] = True
    state["entry_price"] = c
    state["entry_atr"] = a
    state["entry_t"] = t
    state["be"] = False
    state["day_count"] = state.get("day_count", 0) + 1
    return {"target": 1.0, "stop": None, "take": None}

import math
import numpy as np


def clear_trade(state):
    for k in ("in_trade", "dir", "entry", "eatr", "entry_t", "be"):
        if k in state:
            del state[k]


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])

    ema10 = ind.ema(close, 10)
    ema200 = ind.ema(close, 200)
    atr = ind.atr(hist, 14)
    cur_atr = float(atr[-1])

    # 1h trend filter (last completed 1h candle)
    h1 = hist.htf(60)
    trend_up = False
    trend_dn = False
    if len(h1) >= 1:
        h1c = h1.close
        h1e = ind.ema(h1c, 50)
        lc = float(h1c[-1])
        le = float(h1e[-1])
        if not (math.isnan(lc) or math.isnan(le)):
            trend_up = lc > le
            trend_dn = lc < le

    cross_up = False
    cross_dn = False
    if len(close) >= 2:
        p10, p200 = float(ema10[-2]), float(ema200[-2])
        n10, n200 = float(ema10[-1]), float(ema200[-1])
        cross_up = (p10 <= p200) and (n10 > n200)
        cross_dn = (p10 >= p200) and (n10 < n200)

    long_sig = cross_up and trend_up
    short_sig = cross_dn and trend_dn

    # Sync state with actual position
    if state.get("in_trade", False):
        if pos == 0.0 and t > int(state.get("entry_t", t)):
            clear_trade(state)

    if state.get("in_trade", False):
        d = int(state["dir"])
        entry = float(state["entry"])
        eatr = float(state["eatr"])
        entry_t = int(state["entry_t"])

        # breakeven activation (on closes, inclusive)
        if not state.get("be", False):
            if d * (c - entry) >= eatr:
                state["be"] = True
        stop = entry if state.get("be", False) else None

        # opposite signal -> flat
        if (d > 0 and short_sig) or (d < 0 and long_sig):
            return {"target": 0.0, "stop": stop, "take": None}

        # time out
        if t - entry_t >= 128:
            return {"target": 0.0, "stop": stop, "take": None}

        return {"target": pos if pos != 0.0 else d * float(state.get("size", 0.0)),
                "stop": stop, "take": None}

    # Flat: look for entries
    if pos != 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    day = int(hist.time[-1]) // 86400000
    if int(state.get("last_entry_day", -1)) == day:
        return {"target": 0.0, "stop": None, "take": None}

    if (long_sig or short_sig) and cur_atr > 0 and not math.isnan(cur_atr):
        d = 1 if long_sig else -1
        size = 0.01 * c / (3.0 * cur_atr)
        size = max(0.05, min(1.0, size))
        state["in_trade"] = True
        state["dir"] = d
        state["entry"] = c
        state["eatr"] = cur_atr
        state["entry_t"] = t
        state["be"] = False
        state["size"] = size
        state["last_entry_day"] = day
        return {"target": d * size, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

import math
import numpy as np

FAST = 20
SLOW = 200
CLIP = 0.25
MAX_POS = 1.0
COOLDOWN_BARS = 48          # 12 hours of 15-minute bars
ADD_ATR = 2.0
DAY_MS = 86400000


def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close
    c = float(close[-1])

    fast = ind.sma(close, FAST)
    slow = ind.sma(close, SLOW)
    atr = ind.atr(hist, 14)

    f0, f1 = float(fast[-1]), float(fast[-2])
    s0, s1 = float(slow[-1]), float(slow[-2])
    a0 = float(atr[-1])

    if any(math.isnan(v) for v in (f0, f1, s0, s1)):
        return {"target": pos, "stop": None, "take": None}

    golden = f1 <= s1 and f0 > s0
    death = f1 >= s1 and f0 < s0

    day = int(hist.time[-1]) // DAY_MS

    # Position was closed outside our control (not expected here): start the cooldown
    if pos == 0.0 and state.get("in_trade", False):
        state["in_trade"] = False
        state["flat_bar"] = t

    if pos != 0.0:
        d = 1 if pos > 0 else -1

        # An opposite signal closes the trade at the next open (no reversal)
        if (d == 1 and death) or (d == -1 and golden):
            state["in_trade"] = False
            state["flat_bar"] = t + 1   # flat from the next bar's open
            return {"target": 0.0, "stop": None, "take": None}

        # Scale in: trade is in profit and price has moved >= 2 entry ATR from the last fill
        entry = state.get("entry", c)
        last_fill = state.get("last_fill", entry)
        atr_e = state.get("atr_e", a0)
        if pos * d < MAX_POS - 1e-9 and atr_e > 0:
            in_green = (c - entry) * d > 0
            moved = (c - last_fill) * d >= ADD_ATR * atr_e
            if in_green and moved:
                new_t = min(MAX_POS, abs(pos) + CLIP) * d
                state["last_fill"] = c
                return {"target": new_t, "stop": None, "take": None}

        return {"target": pos, "stop": None, "take": None}

    # Flat: look for a new entry
    if golden or death:
        if state.get("last_entry_day", -1) == day:
            return {"target": 0.0, "stop": None, "take": None}
        if "flat_bar" in state and t - state["flat_bar"] < COOLDOWN_BARS:
            return {"target": 0.0, "stop": None, "take": None}
        if math.isnan(a0):
            return {"target": 0.0, "stop": None, "take": None}
        d = 1 if golden else -1
        state["in_trade"] = True
        state["entry"] = c
        state["last_fill"] = c
        state["atr_e"] = a0
        state["last_entry_day"] = day
        return {"target": CLIP * d, "stop": None, "take": None}

    return {"target": 0.0, "stop": None, "take": None}
